        expect(imageEntry.matchesContent(of: ClipboardHistoryEntry(text: "",
                                                                   kind: .image,
                                                                   imageFile: "b.png",
                                                                   imageHash: "h1")),
               "clipboard image dedupe matches by content hash, not by file")
        expect(!imageEntry.matchesContent(of: ClipboardHistoryEntry(text: "",
                                                                    kind: .image,
                                                                    imageFile: "c.png",
                                                                    imageHash: "h2")),
