        expect(ShelfTileLayout.columnCount(contentWidth: 40,
                                           tileWidth: 78,
                                           spacing: 10,
                                           inset: 4) == 1,
               "a width too small for one tile still reports a single column")

        let revealTile = CGSize(width: 78, height: 88)
        expect(ShelfTileLayout.tileFrame(index: 0,
