        expect(ShelfTileLayout.tileFrame(index: 6,
                                         columns: 3,
                                         tileSize: revealTile,
                                         spacing: 10,
                                         inset: 4) == CGRect(x: 4, y: 200, width: 78, height: 88),
               "the seventh tile lands on the third row, the case this change exists for")
        expect(ShelfTileLayout.tileFrame(index: 2,
                                         columns: 1,
                                         tileSize: revealTile,
                                         spacing: 10,
                                         inset: 4) == CGRect(x: 4, y: 200, width: 78, height: 88),
