        let shelfRoundTrip = [shelfFile, shelfText, shelfLink,
                              ShelfPersistedItem(id: UUID(), kind: .batch, title: "batch",
                                                 children: [shelfFile, shelfText])]
        if let encoded = try? JSONEncoder().encode(shelfRoundTrip),
