                && ScreenshotSupport.Tool.shortcutTool(number: 9,
                                                       orderRaw: nil,
                                                       enabled: true) == .freehand
                && ScreenshotSupport.Tool.shortcutTool(number: 1,
                                                       orderRaw: nil,
                                                       enabled: false) == nil
                && ScreenshotSupport.Tool.shortcutTool(number: 10,
