        let scratchpadViewSource = (try? String(
            contentsOfFile: "Sources/Vorssaint/UI/Scratchpad/ScratchpadView.swift",
            encoding: .utf8)) ?? ""
        let scratchpadHitTargetContracts = [
            "Image(systemName: \"plus\")\n                    .font(.system(size: 12, weight: .semibold))\n                    .frame(width: 22, height: 22)\n                    .contentShape(Rectangle())",
            "Image(systemName: \"ellipsis\")\n                    .font(.system(size: 12, weight: .semibold))\n                    .frame(width: 22, height: 22)\n                    .contentShape(Rectangle())",
            ".fill(selected ? Color.accentColor.opacity(0.16) : Color.clear)\n                }\n                .contentShape(RoundedRectangle(cornerRadius: 6, style: .continuous))",
            "Image(systemName: service.isPinned ? \"pin.fill\" : \"pin\")\n                    .font(.system(size: 12, weight: .semibold))\n                    .frame(width: 22, height: 22)\n                    .contentShape(Rectangle())",
            "Image(systemName: \"xmark.circle.fill\")\n                    .font(.system(size: 14))\n                    .foregroundStyle(.secondary)\n                    .frame(width: 22, height: 22)\n                    .contentShape(Rectangle())",
        ]
        expect(scratchpadHitTargetContracts.allSatisfy { scratchpadViewSource.contains($0) },
               "the scratchpad tab bar and header controls keep their full padded hit targets")
        // An unpinned borderless Menu claims the free width of its row on
        // macOS 15 and starves whatever shares that row (issue #569), so the
        // rule is checked for every borderless menu in the app rather than for
        // the one this fix touches. Kill Process is the one
        // deliberate exception: its row controls take a shared minimum width
        // so the Kill button and the menu beside it line up down the list.
        let borderlessMenuException = "KillProcess/KillProcessView"
        var unpinnedBorderlessMenus: [String] = []
        let uiFiles = FileManager.default
            .enumerator(atPath: "Sources/Vorssaint/UI")?
            .compactMap { $0 as? String }
            .filter { $0.hasSuffix(".swift") && !$0.contains(" 2") } ?? []
        for file in uiFiles.sorted() {
            let path = "Sources/Vorssaint/UI/\(file)"
            guard !file.contains(borderlessMenuException),
                  let source = try? String(contentsOfFile: path, encoding: .utf8) else { continue }
            let lines = source.components(separatedBy: "\n")
            for (index, line) in lines.enumerated()
            where line.contains(".menuStyle(.borderlessButton)") {
                // Read to the end of the menu's own modifier chain: the next
                // line that is neither a modifier nor a comment belongs to
                // something else.
                var pinned = false
                var cursor = index + 1
                while cursor < lines.count {
                    let text = lines[cursor].trimmingCharacters(in: .whitespaces)
                    guard text.hasPrefix(".") || text.hasPrefix("//") else { break }
                    if text.hasPrefix(".fixedSize()") { pinned = true; break }
                    cursor += 1
                }
                if !pinned { unpinnedBorderlessMenus.append("\(file):\(index + 1)") }
            }
        }
        expect(unpinnedBorderlessMenus.isEmpty,
               "every borderless menu keeps its own size: \(unpinnedBorderlessMenus)")

        // `waitUntilAllOperationsAreFinished` has no deadline, and the window
        // walk that used it runs on the main thread while its operations run on
        // the shared dispatch pool. Once unrelated work had taken every worker
        // in that pool, not one operation started and the wait never returned,
        // taking the whole app with it (issue #971). The call is unusable here
        // for that reason, so the rule is the absence of it rather than the one
        // caller that was found holding it.
        var unboundedOperationWaits: [String] = []
        let appSources = FileManager.default
            .enumerator(atPath: "Sources/Vorssaint")?
            .compactMap { $0 as? String }
            .filter { $0.hasSuffix(".swift") && !$0.contains(" 2") } ?? []
        for file in appSources.sorted() {
            guard let source = try? String(contentsOfFile: "Sources/Vorssaint/\(file)",
                                           encoding: .utf8) else { continue }
            for (index, line) in source.components(separatedBy: "\n").enumerated()
            where line.contains("waitUntilAllOperationsAreFinished") {
                unboundedOperationWaits.append("\(file):\(index + 1)")
            }
        }
        expect(!appSources.isEmpty && unboundedOperationWaits.isEmpty,
               "no operation queue is waited on without a deadline: \(unboundedOperationWaits)")

        // Asking an application element for its role switches a Chromium app's
        // renderers into full accessibility mode for the rest of the process's
        // life (issue #953). It was fixed at the liveness probe, then found
        // again in the walk up an element's parents, where the chain above a
        // window is the application element — so the rule is the absence of
        // that read anywhere, rather than one grep per door somebody noticed.
        // This is a text scan, not dataflow: it knows an element is an
        // application element only when the same file names it in a `let x =
        // AXUIElementCreateApplication(...)`, and it reads the role attribute
        // and its element off one line. An application element handed to a
        // helper, stored in a property, or passed inline is still on review to
        // catch; both reads found so far were written the direct way.
        // Both scans below report real line numbers, so neither may filter its
        // array before enumerating: comments drop out in the predicate instead.
        func isCommentLine(_ line: String) -> Bool {
            line.trimmingCharacters(in: .whitespaces).hasPrefix("//")
        }
        var applicationRoleReads: [String] = []
        for file in appSources.sorted() {
            guard let source = try? String(contentsOfFile: "Sources/Vorssaint/\(file)",
                                           encoding: .utf8) else { continue }
            let lines = source.components(separatedBy: "\n")
            var applicationElements: Set<String> = []
            for line in lines where line.contains("AXUIElementCreateApplication(") {
                let assigned = (line.components(separatedBy: "=").first ?? "")
                    .trimmingCharacters(in: .whitespaces)
                    .components(separatedBy: " ")
                guard assigned.count == 2, assigned[0] == "let" || assigned[0] == "var" else { continue }
                applicationElements.insert(assigned[1])
            }
            for (index, line) in lines.enumerated()
            where line.contains("kAXRoleAttribute")
                && !isCommentLine(line)
                && applicationElements.contains(where: { line.contains("(\($0), ") }) {
                applicationRoleReads.append("\(file):\(index + 1)")
            }
        }
        expect(!appSources.isEmpty && applicationRoleReads.isEmpty,
               "no application element is ever asked for its role: \(applicationRoleReads)")
        // The scan above cannot see the other way in: a walk up kAXParent asks
        // `parent` for its role, and the application element is what sits above
        // the last window, so the element it reads is never named after one.
        // Two files carried the same walk, so the rule is that anywhere doing
        // it stops at the application element first, rather than a pin per copy.
        var unguardedParentWalks: [String] = []
        for file in appSources.sorted() {
            guard let source = try? String(contentsOfFile: "Sources/Vorssaint/\(file)",
                                           encoding: .utf8) else { continue }
            let lines = source.components(separatedBy: "\n")
            // Per occurrence and in order: a guard sitting anywhere in the file
            // would let a second walk go unguarded, and one written after the
            // read would let the read happen first, which is the whole failure.
            for (index, line) in lines.enumerated()
            where line.contains("role(of: parent)") && !isCommentLine(line) {
                // The window reads raw lines so the report above stays in real
                // line numbers; a commented-out guard must not count as one.
                let guarded = lines[max(0, index - 3)..<index]
                    .contains { $0.contains("isApplicationElement(parent)") && !isCommentLine($0) }
                if !guarded { unguardedParentWalks.append("\(file):\(index + 1)") }
            }
        }
        expect(!appSources.isEmpty && unguardedParentWalks.isEmpty,
               "a walk up the parent chain stops at the application element: \(unguardedParentWalks)")
        expect(ScratchpadRetention.sanitized("day") == .day
                && ScratchpadRetention.sanitized("week") == .week
                && ScratchpadRetention.sanitized("month") == .month
                && ScratchpadRetention.sanitized(nil) == .never
                && ScratchpadRetention.sanitized("yesterday") == .never,
               "scratchpad retention sanitizes to the allowed periods and falls back to never")
        expect(ScratchpadRetention.never.maxIdleInterval == nil
                && ScratchpadRetention.day.maxIdleInterval == 86_400
                && ScratchpadRetention.week.maxIdleInterval == 7 * 86_400
                && ScratchpadRetention.month.maxIdleInterval == 30 * 86_400,
               "scratchpad retention periods are a day, a week and thirty days")
        expect(ScratchpadSupport.dismissesOnOutsideClick(isPinned: false, exportModalActive: false)
                && !ScratchpadSupport.dismissesOnOutsideClick(isPinned: true, exportModalActive: false)
                && !ScratchpadSupport.dismissesOnOutsideClick(isPinned: false, exportModalActive: true),
               "the scratchpad pin and export dialog both block outside-click dismissal")
        let markdownPreview = ScratchpadSupport.markdownPreview(
            "# Heading\n\n**Bold** and *italic* with [link](https://example.com)\n\n- First\n- Second\n\n1. Third\n\n```\ncode\n```")
        expect(markdownPreview.map(\.kind) == [
                    .heading(1), .paragraph,
                    .unorderedListItem(depth: 1), .unorderedListItem(depth: 1),
                    .orderedListItem(ordinal: 1, depth: 1), .code
                ]
                && String(markdownPreview[0].text.characters) == "Heading"
                && String(markdownPreview[2].text.characters) == "First"
                && String(markdownPreview[5].text.characters) == "code"
                && markdownPreview[2].containerID == markdownPreview[3].containerID
                && markdownPreview[2].containerID != nil
                && markdownPreview[3].containerID != markdownPreview[4].containerID
                && markdownPreview[1].text.runs.contains {
                    $0.inlinePresentationIntent?.contains(.stronglyEmphasized) == true
                }
                && markdownPreview[1].text.runs.contains {
                    $0.inlinePresentationIntent?.contains(.emphasized) == true
                }
                && markdownPreview[1].text.runs.contains { $0.link != nil },
               "the scratchpad preview renders semantic blocks and inline formatting")
        expect(Defaults.registeredDefaults[DefaultsKey.scratchpadBackgroundOpacity] as? Double == 0.0,
               "the scratchpad keeps its familiar translucent background by default")
        expect(SettingsBackupSupport.exportKeys().contains(DefaultsKey.scratchpadBackgroundOpacity),
               "the scratchpad background choice travels with the settings backup")
        expect(ScratchpadSupport.sanitizedBackgroundOpacity(0.7) == 0.7,
               "a scratchpad background opacity inside the range is kept")
        expect(ScratchpadSupport.sanitizedBackgroundOpacity(0)
                == ScratchpadSupport.backgroundOpacityRange.lowerBound
                && ScratchpadSupport.sanitizedBackgroundOpacity(-3)
                == ScratchpadSupport.backgroundOpacityRange.lowerBound,
               "the scratchpad background never goes below the familiar translucent style")
        expect(ScratchpadSupport.sanitizedBackgroundOpacity(4) == 1.0
                && ScratchpadSupport.sanitizedBackgroundOpacity(.nan) == 1.0
                && ScratchpadSupport.sanitizedBackgroundOpacity(.infinity) == 1.0,
               "a high or broken scratchpad opacity falls back to fully opaque")
        let scratchpadNow = Date(timeIntervalSince1970: 1_784_000_000)
        expect(!ScratchpadSupport.shouldClear(lastEdited: nil, now: scratchpadNow, retention: .day)
                && !ScratchpadSupport.shouldClear(lastEdited: scratchpadNow.addingTimeInterval(-90_000),
                                                  now: scratchpadNow, retention: .never)
                && !ScratchpadSupport.shouldClear(lastEdited: scratchpadNow.addingTimeInterval(-3_600),
                                                  now: scratchpadNow, retention: .day)
                && ScratchpadSupport.shouldClear(lastEdited: scratchpadNow.addingTimeInterval(-90_000),
                                                 now: scratchpadNow, retention: .day)
                && !ScratchpadSupport.shouldClear(lastEdited: scratchpadNow.addingTimeInterval(-90_000),
                                                  now: scratchpadNow, retention: .week)
                && ScratchpadSupport.shouldClear(lastEdited: scratchpadNow.addingTimeInterval(-8 * 86_400),
                                                 now: scratchpadNow, retention: .week)
                && !ScratchpadSupport.shouldClear(lastEdited: scratchpadNow.addingTimeInterval(60),
                                                  now: scratchpadNow, retention: .day),
               "the scratchpad only clears when a period is chosen and the last edit is older than it")
        let scratchpadExportName = ScratchpadSupport.exportFileName(title: "Scratchpad",
                                                                    date: scratchpadNow)
        expect(scratchpadExportName.hasPrefix("Scratchpad 20")
                && scratchpadExportName.hasSuffix(".txt")
                && scratchpadExportName.count == "Scratchpad ".count + 14,
               "scratchpad export file name is the title plus the local date")
        let firstPadID = UUID(uuidString: "00000000-0000-0000-0000-000000000001")!
        let secondPadID = UUID(uuidString: "00000000-0000-0000-0000-000000000002")!
        let thirdPadID = UUID(uuidString: "00000000-0000-0000-0000-000000000003")!
        let migratedScratchpad = ScratchpadSupport.migratedLegacyDocument(
            text: "existing text",
            lastEdited: scratchpadNow.addingTimeInterval(-120),
            defaultName: "Scratchpad",
            retention: .day,
            now: scratchpadNow,
            id: firstPadID)
        expect(migratedScratchpad.pads.count == 1
                && migratedScratchpad.pads[0].id == firstPadID
                && migratedScratchpad.pads[0].text == "existing text"
                && migratedScratchpad.selectedID == firstPadID,
               "the legacy scratchpad becomes the first selected tab without losing text")
        let twoPads = migratedScratchpad.addingPad(defaultName: "Scratchpad", id: secondPadID)
        let threePads = twoPads?.addingPad(defaultName: "Scratchpad", id: thirdPadID)
        expect(threePads?.pads.map(\.name) == ["Scratchpad 1", "Scratchpad 2", "Scratchpad 3"]
                && threePads?.pads.map(\.id) == [firstPadID, secondPadID, thirdPadID]
                && threePads?.selectedID == thirdPadID,
               "new scratchpads append in order, receive clear names and become selected")
        expect(ScratchpadSupport.nextPadName(defaultName: "Scratchpad",
                                             existingNames: ["Scratchpad"]) == "Scratchpad 2",
               "an existing unnumbered scratchpad still occupies the first numbered slot")
        let renamedPad = threePads?.renaming(secondPadID, to: "  Work\nideas  ")
        expect(renamedPad?.pads[1].name == "Work ideas"
                && ScratchpadSupport.sanitizedPadName(String(repeating: "x", count: 50)).count
                    == ScratchpadDocument.maximumNameLength
                && threePads?.renaming(secondPadID, to: "   ") == nil,
               "scratchpad names stay single-line, bounded and never empty")
        let selectedFirst = renamedPad?.selecting(firstPadID)
        let removedFirst = selectedFirst?.removing(firstPadID)
        expect(removedFirst?.pads.map(\.id) == [secondPadID, thirdPadID]
                && removedFirst?.selectedID == secondPadID,
               "closing the selected scratchpad keeps order and selects its nearest neighbor")
        expect(migratedScratchpad.removing(firstPadID) == nil,
               "the last scratchpad cannot be closed")
        expect(ScratchpadSupport.requiresCloseConfirmation(migratedScratchpad.pads[0])
                && !ScratchpadSupport.requiresCloseConfirmation(
                    ScratchpadDocument.initial(defaultName: "Scratchpad").pads[0]),
               "only closing a scratchpad with content needs destructive confirmation")
        var limitedScratchpads = migratedScratchpad
        for _ in 2...ScratchpadDocument.maximumPadCount {
            limitedScratchpads = limitedScratchpads.addingPad(defaultName: "Scratchpad")!
        }
        expect(limitedScratchpads.pads.count == ScratchpadDocument.maximumPadCount
                && limitedScratchpads.addingPad(defaultName: "Scratchpad") == nil,
               "scratchpads keep a small fixed upper bound")
        var retainedScratchpads = ScratchpadDocument.initial(
            defaultName: "Scratchpad",
            id: firstPadID,
            text: "expired text",
            modifiedAt: scratchpadNow.addingTimeInterval(-90_000))
        retainedScratchpads = retainedScratchpads.addingPad(defaultName: "Scratchpad",
                                                             id: secondPadID)!
        retainedScratchpads.updateSelectedText("recent text",
                                               modifiedAt: scratchpadNow.addingTimeInterval(-300))
        retainedScratchpads.applyRetention(.day, now: scratchpadNow)
        expect(retainedScratchpads.pads[0].text.isEmpty
                && retainedScratchpads.pads[1].text == "recent text",
               "retention clears only scratchpads whose own text expired")
        let scratchpadDocumentData = renamedPad?.encoded()
        let decodedScratchpads = ScratchpadDocument.decoded(scratchpadDocumentData,
                                                            defaultName: "Scratchpad")
        expect(decodedScratchpads == renamedPad,
               "scratchpad text, names, order and selection round-trip together")
        let scratchpadBackup = SettingsBackupSupport.payload(appVersion: "test") { key in
            key == DefaultsKey.scratchpadDocument ? scratchpadDocumentData : nil
        }
        let restoredScratchpadSettings = SettingsBackupSupport.sanitizedSettings(from: scratchpadBackup)
        let restoredScratchpads = ScratchpadDocument.decoded(
            restoredScratchpadSettings?[DefaultsKey.scratchpadDocument] as? Data,
            defaultName: "Scratchpad")
        expect(restoredScratchpads == renamedPad
                && scratchpadDocumentData.map {
                    SettingsBackupSupport.valueLooksRight(DefaultsKey.scratchpadDocument, $0)
                } == true
                && !SettingsBackupSupport.valueLooksRight(DefaultsKey.scratchpadDocument, "broken"),
               "settings backup restores the complete scratchpad document and rejects wrong types")
        let safeScratchpadExportName = ScratchpadSupport.exportFileName(
            title: "Work/Ideas: 1", date: scratchpadNow)
        expect(safeScratchpadExportName.hasPrefix("Work-Ideas- 1 ")
                && !safeScratchpadExportName.contains("/")
                && !safeScratchpadExportName.contains(":"),
               "scratchpad export names cannot turn tab names into path components")

        // Muting every microphone, not just the one the Mac is set to: an app
        // pointed at a device of its own has to go silent too.
        expect(MicMuteSupport.isOwnDevice(name: "Vorssaint Mixer")
                && !MicMuteSupport.isOwnDevice(name: "MacBook Air Microphone"),
               "the mute skips the app's own mixing device and no other")
        expect(!MicMuteSupport.shouldSaveVolume(nil)
                && !MicMuteSupport.shouldSaveVolume(0)
                && !MicMuteSupport.shouldSaveVolume(0.005)
                && MicMuteSupport.shouldSaveVolume(0.4),
               "a level worth restoring is remembered and a silent one never is")
        expect(MicMuteSupport.volumeToRestore(uid: "mic-a",
                                              saved: ["mic-a": 0.4, "mic-b": 0.9],
                                              legacy: 0.6) == 0.4
                && MicMuteSupport.volumeToRestore(uid: "mic-c",
                                                  saved: ["mic-a": 0.4],
                                                  legacy: 0.6) == 0.6
                && MicMuteSupport.volumeToRestore(uid: "mic-c", saved: [:], legacy: 0)
                    == MicMuteSupport.fallbackVolume
                && MicMuteSupport.volumeToRestore(uid: "mic-a",
                                                  saved: ["mic-a": 0],
                                                  legacy: 0) == MicMuteSupport.fallbackVolume,
               "each microphone gets its own level back, then the older single level, then a usable one")
        expect(MicMuteSupport.restoreTargets(recorded: ["mic-a", "gone"],
                                             present: ["mic-a", "mic-b"]) == ["mic-a"]
                && MicMuteSupport.restoreTargets(recorded: nil,
                                                 present: ["mic-a", "mic-b"]) == ["mic-a", "mic-b"]
                && MicMuteSupport.restoreTargets(recorded: [],
                                                 present: ["mic-a", "mic-b"]).isEmpty
                && MicMuteSupport.restoreTargets(recorded: ["mic-a"], present: []).isEmpty,
               "unmuting touches the microphones this app muted, every one with no record, and none when the record is empty")

        expect(Defaults.registeredDefaults[DefaultsKey.radialMenuEnabled] as? Bool == false,
               "the radial menu ships off by default")
        expect(Defaults.registeredDefaults[DefaultsKey.radialMenuShortcut] as? String
                == "control+option+command:49",
               "the default radial menu shortcut is control option command space")
        expect(Defaults.registeredDefaults[DefaultsKey.radialMenuAtPointer] as? Bool == true,
               "the radial menu opens at the pointer by default")
        expect(Defaults.registeredDefaults[DefaultsKey.radialMenuMouseButton] as? String == "off",
               "the side button trigger ships off")
        expect(Defaults.registeredDefaults[DefaultsKey.radialMenuActivationMode] as? String == "pressOrHold",
               "the radial menu preserves its adaptive gesture by default")
        expect(RadialMenuActivationMode.sanitized("press") == .press
                && RadialMenuActivationMode.sanitized("hold") == .hold
                && RadialMenuActivationMode.sanitized(nil) == .pressOrHold
                && RadialMenuActivationMode.sanitized("future-mode") == .pressOrHold,
               "the radial activation mode decodes known values and safely falls back")
        expect(!RadialMenuActivationMode.press.startsHeld(
                    requestedHold: true, hasHeldButton: false, shortcutHasModifiers: true)
                && RadialMenuActivationMode.hold.startsHeld(
                    requestedHold: true, hasHeldButton: false, shortcutHasModifiers: true)
                && RadialMenuActivationMode.pressOrHold.startsHeld(
                    requestedHold: false, hasHeldButton: true, shortcutHasModifiers: false)
                && !RadialMenuActivationMode.hold.startsHeld(
                    requestedHold: false, hasHeldButton: false, shortcutHasModifiers: true),
               "only hold-capable summons enter the held phase")
        expect(RadialMenuActivationMode.pressOrHold.releaseAction(hasSelection: false) == .stayOpen
                && RadialMenuActivationMode.hold.releaseAction(hasSelection: false) == .dismiss
                && RadialMenuActivationMode.hold.releaseAction(hasSelection: true) == .select,
               "release keeps the adaptive wheel, dismisses an empty strict hold, or selects its target")
        expect(RadialMenuSupport.shortcutIsStillHeld(modifiersHeld: true, superKeyHeld: false)
                && RadialMenuSupport.shortcutIsStillHeld(modifiersHeld: false, superKeyHeld: true)
                && !RadialMenuSupport.shortcutIsStillHeld(modifiersHeld: false, superKeyHeld: false),
               "the radial hold follows physical modifiers or the virtual super key")
        expect(RadialMenuMouseTrigger.sanitized("back") == .back
                && RadialMenuMouseTrigger.sanitized("forward").buttonNumber == 4
                && RadialMenuMouseTrigger.back.buttonNumber == 3
                && MouseButtonShortcutSupport.buttonRange.allSatisfy {
                    RadialMenuMouseTrigger.sanitized(
                        RadialMenuMouseTrigger.button($0).rawValue).buttonNumber == $0
                }
                && RadialMenuMouseTrigger.sanitized(nil) == .off
                && RadialMenuMouseTrigger.sanitized("teleport") == .off
                && RadialMenuMouseTrigger.sanitized("button:2") == .off
                && RadialMenuMouseTrigger.sanitized("button:32") == .off
                && RadialMenuMouseTrigger.off.buttonNumber == nil,
               "the mouse trigger round-trips every extra button and falls back to off")
        expect(RadialMenuMouseTrigger.back.buttonNumber == MouseNavigationSupport.backButtonNumber
                && RadialMenuMouseTrigger.forward.buttonNumber == MouseNavigationSupport.forwardButtonNumber,
               "the wheel and mouse navigation agree on which button is which")
        expect(!RadialMenuSupport.claimsMouseButton(3) && !RadialMenuSupport.claimsMouseButton(4),
               "with the feature off no side button is claimed away from navigation")
        expect(Defaults.registeredDefaults[DefaultsKey.panelControlRadialMenu] as? Bool == true,
               "the radial menu panel row ships visible like its siblings")
        expect(Defaults.registeredDefaults[DefaultsKey.radialMenuItems] == nil,
               "the items blob has no registered default so a fresh install detects the starter wheel")
        expect(GlobalShortcutRole.radialMenu.requiredEnableKeys == [DefaultsKey.radialMenuEnabled]
                && GlobalShortcutRole.radialMenu.feature == .radialMenu,
               "the radial menu shortcut role gates on the feature toggle")

        // MARK: Mouse button shortcuts (issue #282)

        expect(Defaults.registeredDefaults[DefaultsKey.mouseButtonShortcutsEnabled] as? Bool == false,
               "mouse button shortcuts ship off by default")
        expect((Defaults.registeredDefaults[DefaultsKey.mouseButtonShortcuts] as? [String: String])?.isEmpty == true,
               "the mapping dictionary registers empty so it travels with backups")
        expect(Defaults.registeredDefaults[DefaultsKey.panelControlMouseButtonShortcuts] as? Bool == true,
               "the mouse button shortcuts panel row ships visible like its siblings")
        expect(AppFeature.mouseButtonShortcuts.enabledKeys == [DefaultsKey.mouseButtonShortcutsEnabled]
                && AppFeature.mouseButtonShortcuts.permissions == [.accessibility]
                && AppFeature.mouseButtonShortcuts.group == .mouseKeyboard,
               "the hub knows the feature's switch, permission and group")

        expect(MouseButtonShortcutSupport.canMap(3) && MouseButtonShortcutSupport.canMap(31)
                && MouseButtonShortcutSupport.canMap(MouseButtonShortcutSupport.sideWheelLeftInput)
                && MouseButtonShortcutSupport.canMap(MouseButtonShortcutSupport.sideWheelRightInput)
                && !MouseButtonShortcutSupport.canMap(0) && !MouseButtonShortcutSupport.canMap(1)
                && !MouseButtonShortcutSupport.canMap(2) && !MouseButtonShortcutSupport.canMap(32)
                && !MouseButtonShortcutSupport.canMap(-3),
               "only extra buttons and both side-wheel directions can carry a shortcut")
        expect(MouseButtonShortcutSupport.backButtonNumber == MouseNavigationSupport.backButtonNumber
                && MouseButtonShortcutSupport.forwardButtonNumber == MouseNavigationSupport.forwardButtonNumber,
               "button shortcuts and mouse navigation agree on which button is which")

        let buttonCombo = GlobalShortcut(keyCode: 0, modifiers: [.command, .shift])
        let decodedButtons = MouseButtonShortcutSupport.decode([
            "3": buttonCombo.storageValue,
            "4": "command:11",
            String(MouseButtonShortcutSupport.sideWheelLeftInput): "command:11",
            "2": "command:11",
            "40": "command:11",
            "junk": "command:11",
            "5": "garbage",
            "6": ":48",
        ])
        expect(decodedButtons.count == 3 && decodedButtons[3] == buttonCombo && decodedButtons[4] != nil
                && decodedButtons[MouseButtonShortcutSupport.sideWheelLeftInput] != nil,
               "decoding keeps valid button and side-wheel mappings and drops everything else")
        expect(MouseButtonShortcutSupport.decode(MouseButtonShortcutSupport.encode(decodedButtons))
                == decodedButtons,
               "mappings round-trip through their stored form")
        expect(MouseButtonShortcutSupport.decode(nil).isEmpty,
               "no stored mappings decode to none")
        expect(MouseButtonShortcutSupport.sortedButtons([
            5: buttonCombo,
            MouseButtonShortcutSupport.sideWheelRightInput: buttonCombo,
            MouseButtonShortcutSupport.sideWheelLeftInput: buttonCombo,
            3: buttonCombo,
            12: buttonCombo,
        ]) == [MouseButtonShortcutSupport.sideWheelLeftInput,
               MouseButtonShortcutSupport.sideWheelRightInput, 3, 5, 12],
               "settings rows keep side-wheel directions together before numbered buttons")
        expect(MouseButtonShortcutSupport.sideWheelInput(isContinuous: false,
                                                         vertical: (0, 0, 0),
                                                         horizontal: (1, 0, 0))
                == MouseButtonShortcutSupport.sideWheelLeftInput
                && MouseButtonShortcutSupport.sideWheelInput(isContinuous: false,
                                                             vertical: (0, 0, 0),
                                                             horizontal: (0, -0.25, 0))
                == MouseButtonShortcutSupport.sideWheelRightInput
                && MouseButtonShortcutSupport.sideWheelInput(isContinuous: true,
                                                             vertical: (0, 0, 0),
                                                             horizontal: (0, 0, 3))
                == MouseButtonShortcutSupport.sideWheelLeftInput
                && MouseButtonShortcutSupport.sideWheelInput(isContinuous: true,
                                                             vertical: (0, 0, 0),
                                                             horizontal: (0, 0, 0)) == nil,
               "side-wheel directions follow AppKit's horizontal sign for discrete and continuous mice")
        expect(MouseButtonShortcutSupport.sideWheelInput(isContinuous: false,
                                                         vertical: (2, 2, 20),
                                                         horizontal: (1, 1, 10)) == nil
                && MouseButtonShortcutSupport.sideWheelInput(isContinuous: false,
                                                             vertical: (1, 1, 10),
                                                             horizontal: (1, 1, 10)) == nil
                && MouseButtonShortcutSupport.sideWheelInput(isContinuous: true,
                                                             vertical: (0, 0, 3),
                                                             horizontal: (0, 0, 4))
                == MouseButtonShortcutSupport.sideWheelLeftInput,
               "vertical and diagonal scrolling cannot leak into a side-wheel shortcut")

        var sideWheelGesture = MouseButtonShortcutSupport.SideWheelGestureGate()
        let wheelLeft = MouseButtonShortcutSupport.sideWheelLeftInput
        let wheelRight = MouseButtonShortcutSupport.sideWheelRightInput
        expect(sideWheelGesture.shouldFire(wheelLeft, at: 0)
                && !sideWheelGesture.shouldFire(wheelLeft, at: 10_000_000)
                && sideWheelGesture.shouldFire(wheelRight, at: 20_000_000)
                && !sideWheelGesture.shouldFire(wheelLeft, at: 30_000_000)
                && !sideWheelGesture.shouldFire(wheelRight, at: 40_000_000),
               "one wheel burst fires each deliberate direction exactly once")
        expect(sideWheelGesture.shouldFire(wheelLeft, at: 300_000_001),
               "a quiet gap arms the next side-wheel gesture")
        sideWheelGesture.reset()
        expect(sideWheelGesture.shouldFire(wheelRight, at: 1),
               "stopping the tap clears the side-wheel gesture state")

        expect(MouseButtonShortcutSupport.firesShortcut(for: 3, isAvailable: true, isEnabled: true,
                                                        mappings: [3: buttonCombo],
                                                        claimedByWheel: { _ in false }) == buttonCombo,
               "an available, enabled mapping fires its combination")
        expect(MouseButtonShortcutSupport.firesShortcut(for: 3, isAvailable: true, isEnabled: true,
                                                        mappings: [3: buttonCombo],
                                                        claimedByWheel: { $0 == 3 }) == nil,
               "the radial menu's summoner button never doubles as a shortcut")
        expect(MouseButtonShortcutSupport.firesShortcut(for: 3, isAvailable: false, isEnabled: true,
                                                        mappings: [3: buttonCombo],
                                                        claimedByWheel: { _ in false }) == nil
                && MouseButtonShortcutSupport.firesShortcut(for: 3, isAvailable: true, isEnabled: false,
                                                            mappings: [3: buttonCombo],
                                                            claimedByWheel: { _ in false }) == nil
                && MouseButtonShortcutSupport.firesShortcut(for: 4, isAvailable: true, isEnabled: true,
                                                            mappings: [3: buttonCombo],
                                                            claimedByWheel: { _ in false }) == nil,
               "hub-off, switch-off and unmapped buttons all stay inert")
        expect(!MouseButtonShortcutSupport.claimsButton(3) && !MouseButtonShortcutSupport.claimsButton(4),
               "with the feature off no button is claimed away from navigation")
        expect(MouseButtonShortcutSupport.buttonName(for: 3, strings: .enUS)
                == MouseButtonFeatureStrings.enUS.backButtonName
                && MouseButtonShortcutSupport.buttonName(for: 4, strings: .enUS)
                == MouseButtonFeatureStrings.enUS.forwardButtonName
                && MouseButtonShortcutSupport.buttonName(
                    for: MouseButtonShortcutSupport.sideWheelLeftInput, strings: .enUS) == "Side wheel left"
                && MouseButtonShortcutSupport.buttonName(
                    for: MouseButtonShortcutSupport.sideWheelRightInput, strings: .enUS) == "Side wheel right"
                && MouseButtonShortcutSupport.buttonName(for: 5, strings: .enUS) == "Button 6",
               "buttons and side-wheel directions have clear names")

        // A synthesized press has to carry the same flags a finger produces,
        // or the system matches it against no shortcut of its own (issue #401).
        expect(GlobalShortcut(keyCode: Int64(kVK_ANSI_N), modifiers: [.command, .shift])
                .syntheticEventFlags == [.maskCommand, .maskShift],
               "an ordinary key goes out with its modifiers and nothing else")
        expect(GlobalShortcut(keyCode: Int64(kVK_RightArrow), modifiers: [.control, .command])
                .syntheticEventFlags == [.maskControl, .maskCommand, .maskSecondaryFn, .maskNumericPad],
               "an arrow goes out as a function key of the numeric pad, the way it arrives")
        expect(GlobalShortcut(keyCode: Int64(kVK_F13), modifiers: [.control, .option, .command])
                .syntheticEventFlags
                == [.maskControl, .maskAlternate, .maskCommand, .maskSecondaryFn],
               "an F key goes out as a function key")
        expect(GlobalShortcut(keyCode: Int64(kVK_PageDown), modifiers: [.command])
                .syntheticEventFlags == [.maskCommand, .maskSecondaryFn]
                && GlobalShortcut(keyCode: Int64(kVK_ForwardDelete), modifiers: [.command])
                .syntheticEventFlags == [.maskCommand, .maskSecondaryFn],
               "the navigation block counts as function keys too")
        expect(GlobalShortcut(keyCode: Int64(kVK_ANSI_Keypad5), modifiers: [.control])
                .syntheticEventFlags == [.maskControl, .maskNumericPad],
               "a keypad key goes out as part of the keypad, without the function flag")
        expect(GlobalShortcut(keyCode: Int64(kVK_Delete), modifiers: [.command])
                .syntheticEventFlags == [.maskCommand]
                && GlobalShortcut(keyCode: Int64(kVK_Escape), modifiers: [.command])
                .syntheticEventFlags == [.maskCommand]
                && GlobalShortcut(keyCode: Int64(kVK_Return), modifiers: [.control, .option])
                .syntheticEventFlags == [.maskControl, .maskAlternate],
               "the keys beside them are ordinary and stay ordinary")

        // MARK: Super key (issue #330)

        expect(Defaults.registeredDefaults[DefaultsKey.superKeyEnabled] as? Bool == false,
               "the super key ships off by default")
        expect(Defaults.registeredDefaults[DefaultsKey.superKeySource] as? String
                == SuperKeySource.capsLock.rawValue,
               "the super key keeps Caps Lock as its default source")
        expect(Defaults.registeredDefaults[DefaultsKey.superKeyModifiers] as? String
                == SuperKeySupport.defaultModifierStorageValue,
               "the super key starts with all four modifiers")
        expect(Defaults.registeredDefaults[DefaultsKey.superKeySoloAction] as? String
                == SuperKeySoloAction.none.rawValue,
               "a tap on its own does nothing until the user picks something")
        expect(Defaults.registeredDefaults[DefaultsKey.panelControlSuperKey] as? Bool == true,
               "the super key panel row ships visible like its siblings")
        expect(Defaults.registeredDefaults[DefaultsKey.superKeyMappingApplied] == nil
                && Defaults.registeredDefaults[DefaultsKey.superKeyMappedSource] == nil,
               "mapping recovery state is never registered or backed up")
        expect(!SettingsBackupSupport.exportKeys().contains(DefaultsKey.superKeyMappingApplied)
                && !SettingsBackupSupport.exportKeys().contains(DefaultsKey.superKeyMappedSource)
                && SettingsBackupSupport.exportKeys().contains(DefaultsKey.superKeyEnabled)
                && SettingsBackupSupport.exportKeys().contains(DefaultsKey.superKeySource)
                && SettingsBackupSupport.exportKeys().contains(DefaultsKey.superKeyModifiers)
                && SettingsBackupSupport.exportKeys().contains(DefaultsKey.superKeySoloAction),
               "the Super key preferences travel in a backup, the mapping state stays behind")
        expect(AppFeature.superKey.enabledKeys == [DefaultsKey.superKeyEnabled]
                && AppFeature.superKey.permissions == [.accessibility]
                && AppFeature.superKey.group == .mouseKeyboard
                && AppFeature.superKey.energyProfile == .keyboard,
               "the hub knows the super key's switch and native input switching needs no Automation")
        expect(FeatureVisibilitySupport.features(for: .superKey) == [.superKey]
                && !FeatureVisibilitySupport.isPageVisible(.superKey, isAvailable: { _ in false }),
               "the page leaves the sidebar when the feature is off in the hub")
        expect(SuperKeySoloAction.sanitized("escape") == .escape
                && SuperKeySoloAction.sanitized("capsLock") == .capsLock
                && SuperKeySoloAction.sanitized("inputSource") == .inputSource
                && SuperKeySoloAction.sanitized("nonsense") == SuperKeySoloAction.none
                && SuperKeySoloAction.sanitized(nil) == SuperKeySoloAction.none,
               "a stored solo action is trusted only when the app still knows it")
        expect(SuperKeySource.sanitized("rightCommand") == .rightCommand
                && SuperKeySource.sanitized("nonsense") == .capsLock
                && SuperKeySource.sanitized(nil) == .capsLock
                && SuperKeySource.capsLock.usage == 0x700000039
                && SuperKeySource.rightControl.usage == 0x7000000E4
                && SuperKeySource.rightShift.usage == 0x7000000E5
                && SuperKeySource.rightOption.usage == 0x7000000E6
                && SuperKeySource.rightCommand.usage == 0x7000000E7
                && Set(SuperKeySource.allCases.map(\.usage)).count == SuperKeySource.allCases.count
                && Set(SuperKeySource.allCases.map(\.keyCode)).count == SuperKeySource.allCases.count,
               "stored sources are validated and each supported key has distinct HID data")
        expect(SuperKeySource.capsLock.systemImage == "capslock"
                && SuperKeySource.rightCommand.systemImage == "command"
                && SuperKeySource.rightOption.systemImage == "option"
                && SuperKeySource.rightControl.systemImage == "control"
                && SuperKeySource.rightShift.systemImage == "shift",
               "each super key source has a matching system image")
        expect(SuperKeySupport.modifiers(from: "control+option+command")
                == [.control, .option, .command]
                && SuperKeySupport.modifiers(from: "shift") == .validMask
                && SuperKeySupport.modifiers(from: "control+") == .validMask
                && SuperKeySupport.modifiers(from: "") == .validMask
                && SuperKeySupport.modifiers(from: "invalid") == .validMask
                && SuperKeySupport.modifiers(from: nil) == .validMask,
               "stored Super key modifiers require a shortcut modifier or use the default")
        expect(SuperKeySupport.storageValue(for: [.control, .option, .command])
                == "control+option+command"
                && SuperKeySupport.storageValue(for: [])
                    == SuperKeySupport.defaultModifierStorageValue,
               "Super key modifiers keep stable storage and never save an empty combination")
        expect(SuperKeySupport.soloEffect(action: .none,
                                          longHold: false,
                                          repeated: false) == .none
                && SuperKeySupport.soloEffect(action: .escape,
                                              longHold: false,
                                              repeated: false) == .escape
                && SuperKeySupport.soloEffect(action: .escape,
                                              longHold: true,
                                              repeated: true) == .none
                && SuperKeySupport.soloEffect(action: .capsLock,
                                              longHold: true,
                                              repeated: false) == .capsLock
                && SuperKeySupport.soloEffect(action: .capsLock,
                                              longHold: false,
                                              repeated: true) == .none,
               "existing solo actions keep their tap, hold and repeat behavior")
        expect(SuperKeySupport.soloEffect(action: .inputSource,
                                          longHold: false,
                                          repeated: false) == .inputSource
                && SuperKeySupport.soloEffect(action: .inputSource,
                                              longHold: false,
                                              repeated: true) == .inputSource
                && SuperKeySupport.soloEffect(action: .inputSource,
                                              longHold: true,
                                              repeated: false) == .capsLock
                && SuperKeySupport.soloEffect(action: .inputSource,
                                              longHold: true,
                                              repeated: true) == .capsLock,
               "the input-source action switches on a quick press and reserves a hold for Caps Lock")
        expect(SuperKeySupport.nextInputSourceID(currentID: "abc",
                                                 enabledIDs: ["abc", "pinyin", "kana"]) == "pinyin"
                && SuperKeySupport.nextInputSourceID(currentID: "kana",
                                                     enabledIDs: ["abc", "pinyin", "kana"]) == "abc"
                && SuperKeySupport.nextInputSourceID(currentID: "missing",
                                                     enabledIDs: ["abc", "pinyin"]) == "abc"
                && SuperKeySupport.nextInputSourceID(currentID: nil,
                                                     enabledIDs: ["abc"]) == nil,
               "input sources cycle through the enabled system list without a hard-coded shortcut")

        let capsMapping = SuperKeyMapping(source: SuperKeySource.capsLock.usage,
                                          destination: SuperKeySupport.triggerUsage)
        let rightCommandMapping = SuperKeyMapping(source: SuperKeySource.rightCommand.usage,
                                                  destination: SuperKeySupport.triggerUsage)
        let foreignMapping = SuperKeyMapping(source: 0x700000064, destination: 0x700000035)
        expect(SuperKeySupport.mappings(enablingSuperKey: true, existing: []) == [capsMapping],
               "turning the key on maps caps lock to the key it arrives as")
        expect(SuperKeySupport.mappings(enablingSuperKey: true, existing: [foreignMapping])
                == [capsMapping, foreignMapping],
               "a mapping the user set up elsewhere survives turning the feature on")
        expect(SuperKeySupport.mappings(enablingSuperKey: true,
                                        existing: [capsMapping, foreignMapping],
                                        source: .rightCommand,
                                        ownedSource: .capsLock)
                == [rightCommandMapping, foreignMapping],
               "changing sources removes the old owned mapping before adding the new one")
        expect(SuperKeySupport.mappings(enablingSuperKey: false,
                                        existing: [capsMapping, foreignMapping],
                                        ownedSource: .capsLock)
                == [foreignMapping],
               "turning it off removes only the entry this feature owns")
        let foreignCapsMapping = SuperKeyMapping(source: SuperKeySource.capsLock.usage,
                                                 destination: 0x700000029)
        let foreignRightCommandMapping = SuperKeyMapping(source: SuperKeySource.rightCommand.usage,
                                                         destination: 0x700000029)
        expect(SuperKeySupport.hasMappingConflict(in: [foreignCapsMapping])
                && SuperKeySupport.mappings(enablingSuperKey: true,
                                            existing: [foreignCapsMapping]) == [foreignCapsMapping]
                && SuperKeySupport.mappings(enablingSuperKey: false,
                                            existing: [foreignCapsMapping]) == [foreignCapsMapping],
               "an existing Caps Lock mapping is refused and preserved in both directions")
        expect(SuperKeySupport.hasMappingConflict(in: [foreignRightCommandMapping],
                                                  source: .rightCommand),
               "an existing mapping on a selected right-side source blocks activation")
        expect(SuperKeySupport.hasMappingConflict(in: [capsMapping])
                && !SuperKeySupport.hasMappingConflict(in: [capsMapping],
                                                       ownedSource: .capsLock)
                && SuperKeySupport.mappings(enablingSuperKey: true,
                                            existing: [capsMapping]) == [capsMapping],
               "an identical external Caps Lock mapping is not claimed without ownership proof")
        expect(SuperKeySupport.mappingArgument([capsMapping])
                == "{\"UserKeyMapping\":[{\"HIDKeyboardModifierMappingSrc\":30064771129,\"HIDKeyboardModifierMappingDst\":30064771181}]}",
               "the mapping table goes out in the form the system takes")
        expect(SuperKeySupport.mappingArgument([]) == "{\"UserKeyMapping\":[]}",
               "an empty table clears the mapping")
        expect(SuperKeySupport.mappingsMatch([capsMapping, foreignMapping],
                                             [foreignMapping, capsMapping])
                && !SuperKeySupport.mappingsMatch([capsMapping], [foreignMapping]),
               "mapping readback compares the complete table without depending on its order")
        expect(SuperKeySupport.mappingMarkerAfterClear(previous: true,
                                                       readbackConfirmed: false)
                && !SuperKeySupport.mappingMarkerAfterClear(previous: true,
                                                            readbackConfirmed: true)
                && !SuperKeySupport.mappingMarkerAfterClear(previous: false,
                                                            readbackConfirmed: false),
               "only confirmed clear readback removes the write-ahead mapping marker")
        expect(SuperKeySupport.mappingRequestIsAuthorized(
            requestGeneration: 4,
            currentGeneration: 4,
            tapIsCurrent: true,
            stopping: false
        )
                && !SuperKeySupport.mappingRequestIsAuthorized(
                    requestGeneration: 4,
                    currentGeneration: 5,
                    tapIsCurrent: true,
                    stopping: false
                )
                && !SuperKeySupport.mappingRequestIsAuthorized(
                    requestGeneration: 4,
                    currentGeneration: 4,
                    tapIsCurrent: false,
                    stopping: false
                ),
               "a stop or replaced event tap invalidates a queued Super key mapping")
        expect(SuperKeyMappingGuard.cleanupSource(in: [
            "Vorssaint", SuperKeyMappingGuard.cleanupArgument, "capsLock",
        ]) == .capsLock
                && SuperKeyMappingGuard.cleanupSource(in: [
                    "Vorssaint", SuperKeyMappingGuard.cleanupArgument, "rightCommand",
                ]) == .rightCommand
                && SuperKeyMappingGuard.cleanupSource(in: [
                    "Vorssaint", SuperKeyMappingGuard.cleanupArgument, "invalid",
                ]) == nil,
               "the crash guard accepts only a real Super key source")

        let mappingReport = """
        RegistryID  Key                   Value
        100000a84   UserKeyMapping   (
                {
                HIDKeyboardModifierMappingDst = 30064771181;
                HIDKeyboardModifierMappingSrc = 30064771129;
            }
        )
        100000a85   UserKeyMapping   (
                {
                HIDKeyboardModifierMappingDst = 30064771181;
                HIDKeyboardModifierMappingSrc = 30064771129;
            }
        )
        """
        expect(SuperKeySupport.parseMappings(mappingReport) == [capsMapping],
               "the same entry on two keyboards is read once")
        expect(SuperKeySupport.mappingReportConfirms(mappingReport, expected: [capsMapping]),
               "mapping readback confirms the requested table on every keyboard")
        let partiallyMappedReport = mappingReport + """

        100000a86   UserKeyMapping   (
        )
        """
        expect(!SuperKeySupport.mappingReportConfirms(partiallyMappedReport,
                                                      expected: [capsMapping])
                && !SuperKeySupport.mappingReportConfirms("", expected: []),
               "one unmapped keyboard or a missing readback cannot confirm a global write")
        expect(SuperKeySupport.parseMappings("RegistryID  Key  Value\n100000a84 UserKeyMapping (null)").isEmpty
                && SuperKeySupport.parseMappings("").isEmpty,
               "a keyboard with no mapping reads as none")
        let heterogeneousUserMappingReport = """
        RegistryID  Key                   Value
        100000a84   UserKeyMapping   (
                {
                HIDKeyboardModifierMappingDst = 30064771125;
                HIDKeyboardModifierMappingSrc = 30064771172;
            }
        )
        100000a85   UserKeyMapping   (
        )
        """
        expect(SuperKeySupport.consistentMappings(
            heterogeneousUserMappingReport,
            property: SuperKeySupport.userMappingProperty
        ) == nil, "device-specific key mappings are never copied onto every keyboard")
        let ownedDifferenceReport = """
        RegistryID  Key                   Value
        100000a84   UserKeyMapping   (
                {
                HIDKeyboardModifierMappingDst = 30064771181;
                HIDKeyboardModifierMappingSrc = 30064771129;
            }
                {
                HIDKeyboardModifierMappingDst = 30064771125;
                HIDKeyboardModifierMappingSrc = 30064771172;
            }
        )
        100000a85   UserKeyMapping   (
                {
                HIDKeyboardModifierMappingDst = 30064771125;
                HIDKeyboardModifierMappingSrc = 30064771172;
            }
        )
        """
        expect(SuperKeySupport.consistentMappings(
            ownedDifferenceReport,
            property: SuperKeySupport.userMappingProperty,
            ownedSource: .capsLock
        ) == [foreignMapping], "a newly connected keyboard can converge when only the owned mapping differs")
        expect(SuperKeyMappingGuard.mappingsAfterCleanup(
            ownedDifferenceReport,
            source: .capsLock
        ) == [foreignMapping],
               "the crash guard removes only the mapping owned by the Super key")

        let noActionReport = """
        HIDKeyboardModifierMappingPairs = {
          HIDKeyboardModifierMappingSrc = 30064771129;
          HIDKeyboardModifierMappingDst = "-1";
        }
        """
        expect(SuperKeySupport.parseMappings(noActionReport)
                == [SuperKeyMapping(source: SuperKeySource.capsLock.usage,
                                    destination: UInt64.max)],
               "hidutil's signed no-action value keeps its unsigned HID meaning")
        // The page is the only place a refused mapping is visible, so the
        // reason has to reach it and be spelled out there.
        let superKeySettingsSource = (try? String(
            contentsOfFile: "Sources/Vorssaint/UI/Settings/SuperKeySettings.swift",
            encoding: .utf8)) ?? ""
        let failureMark = superKeySettingsSource.range(of: "superKey.mappingFailure")
        let runningMark = superKeySettingsSource.range(of: "superKey.isRunning")
        expect(failureMark != nil && runningMark != nil
                && failureMark!.lowerBound < runningMark!.lowerBound
                && superKeySettingsSource.contains("text.mappingFailure(failure)"),
               "the Super key page names a refused mapping ahead of the working state")

        var superKeyState = SuperKeySupport.State()
        expect(superKeyState.decide(.otherKey) == .pass,
               "with the key up, typing is untouched")
        expect(superKeyState.decide(.triggerDown(
            isRepeat: false, hasPrimaryModifiers: false, timestamp: 0
        )) == .swallow,
               "the key itself never reaches an app")
        expect(superKeyState.isHeld
                && superKeyState.decide(.otherKey) == .addModifiers
                && superKeyState.decide(.otherKey) == .addModifiers,
               "every key pressed while it is held carries the configured modifiers")
        expect(superKeyState.decide(.triggerUp(timestamp: 1)) == .swallow && !superKeyState.isHeld,
               "releasing after a combination does nothing on its own")

        // What the watchdog leans on: a press whose release never arrived is
        // let go of, and typing goes back to normal without the key being
        // touched again.
        var lostReleaseState = SuperKeySupport.State()
        _ = lostReleaseState.decide(.triggerDown(
            isRepeat: false, hasPrimaryModifiers: false, timestamp: 0
        ))
        expect(lostReleaseState.decide(.otherKey) == .addModifiers,
               "a press with no release still carries the modifiers while it stands")
        lostReleaseState.reset()
        expect(lostReleaseState.decide(.otherKey) == .pass,
               "letting go of a press whose release was lost gives typing back")
        expect(lostReleaseState.decide(.triggerUp(timestamp: 1)) == .swallow,
               "a release arriving after the press was let go does nothing")

        var soloState = SuperKeySupport.State()
        _ = soloState.decide(.triggerDown(
            isRepeat: false, hasPrimaryModifiers: false, timestamp: 1_000_000_000
        ))
        expect(soloState.decide(.triggerUp(timestamp: 1_499_999_999)) == .soloTap(repeated: false),
               "a quick no-repeat press is the solo tap")
        _ = soloState.decide(.triggerDown(
            isRepeat: false, hasPrimaryModifiers: false, timestamp: 2_000_000_000
        ))
        expect(soloState.decide(.triggerDown(
            isRepeat: true, hasPrimaryModifiers: false, timestamp: 2_100_000_000
        )) == .swallow
                && soloState.decide(.triggerUp(timestamp: 2_500_000_000)) == .soloHold(repeated: true),
               "a repeated press held long enough is a repeated solo hold")
        _ = soloState.decide(.triggerDown(
            isRepeat: false, hasPrimaryModifiers: false, timestamp: 3_000_000_000
        ))
        _ = soloState.decide(.otherModifier)
        expect(soloState.decide(.triggerUp(timestamp: 4_000_000_000)) == .swallow,
               "holding it together with another modifier is not a tap either")

        // Drag chords read their modifiers off the mouse-down, not off any
        // keyboard event (#888), so the service must classify mouse presses
        // like other keys and stamp them from a tap at the HID stage — the
        // one place guaranteed to run before every session tap that reads
        // the flags. The service file is not in this binary; pin the shape.
        let superKeyServiceSource = (try? String(
            contentsOfFile: "Sources/Vorssaint/Services/SuperKey/SuperKeyService.swift",
            encoding: .utf8)) ?? ""
        let superKeyServiceCode = superKeyServiceSource
            .split(separator: "\n", omittingEmptySubsequences: false)
            .filter { !$0.trimmingCharacters(in: .whitespaces).hasPrefix("//") }
            .joined(separator: "\n")
        expect(superKeyServiceCode.contains(".leftMouseDown, .rightMouseDown, .otherMouseDown")
               && superKeyServiceCode.contains("mouseDownTypes.reduce(CGEventMask(0))")
               && superKeyServiceCode.contains("mouseDownTypes.contains(type) { return .otherKey }")
               && superKeyServiceCode.range(of: "tap: .cghidEventTap") != nil,
               "every mouse press while the super key is held carries the modifiers, stamped at the HID stage")
        // A mouse event carries no keycode of its own: the field reads back as
        // 0 on one, which is the keycode for A. The read lives inside classify,
        // below the line that answers the mouse types, so no caller holds a
        // phantom key it could hand to something that looks keys up.
        let keycodeReads = superKeyServiceCode
            .components(separatedBy: ".keyboardEventKeycode").count - 1
        let mouseAnswer = superKeyServiceCode.range(of: "mouseDownTypes.contains(type)")?.lowerBound
        let keycodeRead = superKeyServiceCode.range(of: ".keyboardEventKeycode")?.lowerBound
        expect(keycodeReads == 1
               && mouseAnswer.flatMap({ answer in keycodeRead.map { answer < $0 } }) == true,
               "a mouse press is answered before the super key ever reads a keycode")
        // A refused mouse tap counts as dead so the health check rebuilds it,
        // but exactly once: the rebuild takes the healthy keyboard tap down
        // with it, and a system that refuses refuses the retry too, so an
        // unbounded flag would hiccup super-key input at whatever rate
        // syncWithPreferences fires. The count has to outlive the teardown its
        // own value asked for, so the only place it is put back to zero is its
        // own declaration — never the tap thread's reset block, which the
        // rebuild runs and which would start the loop over.
        let refusalResets = superKeyServiceCode
            .components(separatedBy: "mouseTapRefusals = 0").count - 1
        expect(superKeyServiceCode.contains("?? (mouseTapRefusals == 1)")
               && superKeyServiceCode.contains(
                   "mouseTapRefusals = mouseTap == nil ? self.mouseTapRefusals + 1 : 0")
               && refusalResets == 1,
               "a refused mouse tap is worth one rebuild, and the count survives it")

        var noRepeatHoldState = SuperKeySupport.State()
        _ = noRepeatHoldState.decide(.triggerDown(
            isRepeat: false, hasPrimaryModifiers: false, timestamp: 6_000_000_000
        ))
        expect(noRepeatHoldState.decide(.triggerUp(timestamp: 6_500_000_000)) == .soloHold(repeated: false),
               "a no-repeat press at the hold threshold is a solo hold")

        var fastRepeatState = SuperKeySupport.State()
        _ = fastRepeatState.decide(.triggerDown(
            isRepeat: false, hasPrimaryModifiers: false, timestamp: 8_000_000_000
        ))
        expect(fastRepeatState.decide(.triggerDown(
            isRepeat: true, hasPrimaryModifiers: false, timestamp: 8_100_000_000
        )) == .swallow
                && fastRepeatState.decide(.triggerUp(timestamp: 8_499_999_999)) == .soloTap(repeated: true),
               "a fast repeat remains a quick press and records the repeat")

        var preheldModifierState = SuperKeySupport.State()
        _ = preheldModifierState.decide(.triggerDown(
            isRepeat: false, hasPrimaryModifiers: true, timestamp: 7_000_000_000
        ))
        expect(preheldModifierState.isHeld
                && !preheldModifierState.isAlone
                && preheldModifierState.decide(.triggerUp(timestamp: 7_500_000_000)) == .swallow,
               "a pre-held modifier cancels solo action while keeping Superkey held")

        var resetSoloState = SuperKeySupport.State()
        _ = resetSoloState.decide(.triggerDown(
            isRepeat: false, hasPrimaryModifiers: false, timestamp: 0
        ))
        _ = resetSoloState.decide(.triggerDown(
            isRepeat: true, hasPrimaryModifiers: false, timestamp: 1
        ))
        resetSoloState.reset()
        _ = resetSoloState.decide(.triggerDown(
            isRepeat: false, hasPrimaryModifiers: false, timestamp: 5_000_000_000
        ))
        expect(resetSoloState.decide(.triggerUp(timestamp: 5_499_999_999)) == .soloTap(repeated: false),
               "reset clears the previous press timestamp and repeat state")

        var lateRepeatState = SuperKeySupport.State()
        _ = lateRepeatState.decide(.triggerDown(
            isRepeat: false, hasPrimaryModifiers: false, timestamp: 0
        ))
        lateRepeatState.reset()
        expect(lateRepeatState.decide(.triggerDown(
            isRepeat: true, hasPrimaryModifiers: false, timestamp: 1_000_000_000
        )) == .swallow
                && !lateRepeatState.isHeld
                && lateRepeatState.decide(.triggerUp(timestamp: 1_500_000_000)) == .swallow,
               "a repeat after reset cannot revive a solo press")

        var strandedState = SuperKeySupport.State()
        _ = strandedState.decide(.triggerDown(
            isRepeat: false, hasPrimaryModifiers: false, timestamp: 0
        ))
        strandedState.reset()
        expect(strandedState.decide(.otherKey) == .pass,
               "a key held while the tap goes away cannot leave typing stuck in modifiers")
        var unmappedKeyboardState = SuperKeySupport.State()
        expect(unmappedKeyboardState.decide(.sourceKey) == .interceptAndRemap,
               "a raw source key is intercepted while that keyboard's mapping is repaired")

        // MARK: Mouse app exceptions (issue #358)

        expect(MouseExceptionScope.allCases.allSatisfy {
                    (Defaults.registeredDefaults[$0.defaultsKey] as? [String])?.isEmpty == true
               },
               "every feature's exception list registers empty, so they all start out working everywhere")
        expect(Set(MouseExceptionScope.allCases.map(\.defaultsKey)).count == MouseExceptionScope.allCases.count,
               "each feature keeps its own list, never a key shared with another")
        expect(MouseExceptionScope.smoothScroll.feature == .smoothScroll
                && MouseExceptionScope.scrollDirection.feature == .scrollInverter
                && MouseExceptionScope.navigation.feature == .mouseNavigation
                && MouseExceptionScope.buttonShortcuts.feature == .mouseButtonShortcuts
                && MouseExceptionScope.middleClick.feature == .middleClick,
               "each list knows the feature that owns it, so it hides with that feature")
        expect(MouseExceptionScope.allCases.allSatisfy { $0.feature.group == .mouseKeyboard },
               "every exception list belongs to a mouse feature")
        expect(Defaults.sanitizedBundleIdentifierList(["  com.example.a  ", "", "com.example.a", "com.example.b"])
                == ["com.example.a", "com.example.b"],
               "the exception list drops blanks, spaces and repeats")

        let exceptionSet: Set<String> = ["com.example.modeler"]
        expect(MouseAppExceptionSupport.isExcepted("com.example.modeler", exceptions: exceptionSet)
                && !MouseAppExceptionSupport.isExcepted("com.example.other", exceptions: exceptionSet)
                && !MouseAppExceptionSupport.isExcepted(nil, exceptions: exceptionSet)
                && !MouseAppExceptionSupport.isExcepted("com.example.modeler", exceptions: []),
               "an app is excepted only when its identifier is on a list that has entries")
        expect(MouseAppExceptionSupport.isExcepted(["com.example.modeler"],
                                                    exceptions: exceptionSet)
                && MouseAppExceptionSupport.isExcepted(
                    ["com.example.helper", "com.example.modeler"],
                    exceptions: exceptionSet)
                && !MouseAppExceptionSupport.isExcepted(["com.example.other"],
                                                         exceptions: exceptionSet),
               "a source app or one of its bundled helpers can carry an exception")
        // A program started from a launcher — the Java process behind a game
        // is the reported one — has no bundle identifier at all, so the file
        // being run stands in as its identity (issue #1009). An app that has
        // an identifier keeps answering only to that, so nothing already
        // listed changes meaning.
        expect(MouseAppExceptionSupport.identity(bundleID: "com.example.modeler",
                                                 executablePath: "/Applications/Modeler.app/Contents/MacOS/Modeler")
                == "com.example.modeler",
               "an app with a bundle identifier answers to it and not to its executable")
        expect(MouseAppExceptionSupport.identity(bundleID: nil,
                                                 executablePath: "/opt/game/runtime/bin/java")
                == "/opt/game/runtime/bin/java",
               "a program with no bundle identifier answers to the file being run")
        expect(MouseAppExceptionSupport.identity(bundleID: nil, executablePath: nil) == nil
                && MouseAppExceptionSupport.identity(bundleID: nil, executablePath: "java") == nil,
               "a program with nothing to be named by is never excepted by accident")
        expect(MouseAppExceptionSupport.isExecutablePathIdentity("/opt/game/runtime/bin/java")
                && !MouseAppExceptionSupport.isExecutablePathIdentity("com.example.modeler"),
               "a stored path is told from a bundle identifier by its leading slash")
        expect(MouseAppExceptionSupport.isExcepted(
                   MouseAppExceptionSupport.identity(bundleID: nil,
                                                     executablePath: "/opt/game/runtime/bin/java"),
                   exceptions: ["/opt/game/runtime/bin/java"])
                && !MouseAppExceptionSupport.isExcepted(
                    MouseAppExceptionSupport.identity(bundleID: nil,
                                                      executablePath: "/opt/other/bin/java"),
                    exceptions: ["/opt/game/runtime/bin/java"]),
               "a listed program path excepts that program and no other")
        expect(InstalledApps.name(for: "/opt/game/runtime/bin/java") == "java",
               "a listed program path is shown by its file name, not the whole path")

        // The stored path is the one the file sheet handed back and the
        // matched one is the file the running program reports, and the same
        // file arrives at the two ends under different names as soon as
        // anything on the way is a link — measured on this Mac, the sheet
        // answers /private/tmp/… for a file the running program answers
        // /tmp/… for. Both ends resolve, so they meet.
        let identityRoot = FileManager.default.temporaryDirectory
            .appendingPathComponent("vorssaint-identity-\(getpid())", isDirectory: true)
        let runtimeBinary = identityRoot.appendingPathComponent("runtime/bin/launcher")
        try? FileManager.default.createDirectory(at: runtimeBinary.deletingLastPathComponent(),
                                                 withIntermediateDirectories: true)
        FileManager.default.createFile(atPath: runtimeBinary.path, contents: Data())
        let linkedBinary = identityRoot.appendingPathComponent("launcher")
        try? FileManager.default.createSymbolicLink(at: linkedBinary, withDestinationURL: runtimeBinary)
        let pickedThroughLink = MouseAppExceptionSupport.executablePathIdentity(linkedBinary.path)
        let reportedByTheSystem = MouseAppExceptionSupport.identity(bundleID: nil,
                                                                    executablePath: runtimeBinary.path)
        expect(pickedThroughLink != nil
                && pickedThroughLink != linkedBinary.path
                && pickedThroughLink == reportedByTheSystem,
               "a program picked through a link stores the file it links to")
        expect(MouseAppExceptionSupport.isExcepted(reportedByTheSystem,
                                                   exceptions: Set([pickedThroughLink].compactMap { $0 })),
               "the program the system reports matches the entry the picker stored")

        // A file sheet that takes programs can be walked into a bundle, and
        // what is stored has to be what the system will report once the file
        // runs. Measured on this Mac: a bundle's own executable run straight
        // from disk is reported as com.example.withid, while a runtime shipped
        // deeper in that same bundle — the shape issue #1009 is about — is
        // reported with no identifier and stays a path. Filing that runtime
        // under the app above it would break the case this all exists for.
        func makeTestBundle(_ name: String, identifier: String?) -> URL {
            let bundle = identityRoot.appendingPathComponent("\(name).app")
            for file in ["Contents/MacOS/\(name)", "Contents/runtime/bin/java"] {
                let url = bundle.appendingPathComponent(file)
                try? FileManager.default.createDirectory(at: url.deletingLastPathComponent(),
                                                         withIntermediateDirectories: true)
                FileManager.default.createFile(atPath: url.path, contents: Data())
            }
            var info: [String: Any] = ["CFBundleExecutable": name, "CFBundlePackageType": "APPL"]
            if let identifier { info["CFBundleIdentifier"] = identifier }
            if let plist = try? PropertyListSerialization.data(fromPropertyList: info,
                                                               format: .xml,
                                                               options: 0) {
                try? plist.write(to: bundle.appendingPathComponent("Contents/Info.plist"))
            }
            return bundle
        }
        let namedBundle = makeTestBundle("Modeler", identifier: "com.example.modeler")
        let namelessBundle = makeTestBundle("Bare", identifier: nil)
        expect(MouseAppExceptionSupport.pickedIdentity(for: namedBundle) == "com.example.modeler"
                && MouseAppExceptionSupport.pickedIdentity(
                    for: namedBundle.appendingPathComponent("Contents/MacOS/Modeler"))
                    == "com.example.modeler",
               "an app is stored by its identifier whether its bundle or the binary inside it was picked")
        let bundledRuntime = namedBundle.appendingPathComponent("Contents/runtime/bin/java")
        expect(MouseAppExceptionSupport.pickedIdentity(for: bundledRuntime)
                == MouseAppExceptionSupport.executablePathIdentity(bundledRuntime.path),
               "a runtime shipped inside an app keeps its own path, never the identifier of the app above it")
        expect(MouseAppExceptionSupport.pickedIdentity(for: namelessBundle)
                == MouseAppExceptionSupport.executablePathIdentity(
                    namelessBundle.appendingPathComponent("Contents/MacOS/Bare").path),
               "an app whose Info.plist names no identifier is stored by the binary it runs")
        expect(MouseAppExceptionSupport.pickedIdentity(for: runtimeBinary)
                == MouseAppExceptionSupport.executablePathIdentity(runtimeBinary.path),
               "a program that is not packaged as an app is stored by its own file")
        try? FileManager.default.removeItem(at: identityRoot)

        // The list sanitizer runs over stored entries, and a file name may
        // legally end in a space: trimming a path would look for a spelling
        // the running program never reports, so only an identifier is trimmed.
        expect(Defaults.sanitizedBundleIdentifierList(["/opt/game/bin/java ", " com.example.a "])
                == ["/opt/game/bin/java ", "com.example.a"],
               "a stored path keeps its exact file name while an identifier is trimmed")

        expect(InstalledApps.location(for: "com.example.modeler") == nil,
               "a bundle identifier names its app on its own and carries no location")
        expect(InstalledApps.location(for: NSHomeDirectory() + "/runtimes/zulu-8.jre/bin/java")
                == "~/runtimes/zulu-8.jre/bin",
               "a path identity is located by its directory, spelled from home")
        expect(InstalledApps.location(for: "/opt/game/bin/java") == "/opt/game/bin",
               "a path outside home keeps its absolute directory")

        // Both ends of that agreement live outside this binary: the picker
        // stores from AppBundleList and the taps match from MouseAppExceptions.
        // An identity resolved at one end and taken raw at the other silently
        // matches nothing (issue #1009), so what each side may hand on is
        // pinned rather than the spelling it happens to use today — a second
        // way into the list, dropping a file onto it among them, has to go
        // through the same resolver as the sheet does.
        let pickerLines = ((try? String(
            contentsOfFile: "Sources/Vorssaint/UI/Settings/AppBundleList.swift",
            encoding: .utf8)) ?? "").components(separatedBy: "\n")
        var resolvedNames: Set<String> = []
        for line in pickerLines where line.contains("= MouseAppExceptionSupport.") {
            guard let bound = line.components(separatedBy: "let ").last?
                    .components(separatedBy: " =").first else { continue }
            resolvedNames.insert(bound.trimmingCharacters(in: .whitespaces))
        }
        var resolvedAddSites: [String] = []
        var rawAddSites: [String] = []
        for (index, line) in pickerLines.enumerated()
        where !line.trimmingCharacters(in: .whitespaces).hasPrefix("//") && line.contains("onAdd(") {
            let added = (line.components(separatedBy: "onAdd(").last?
                .components(separatedBy: ")").first ?? "").trimmingCharacters(in: .whitespaces)
            if resolvedNames.contains(added) {
                resolvedAddSites.append("AppBundleList.swift:\(index + 1)")
            } else {
                rawAddSites.append("AppBundleList.swift:\(index + 1) adds \(added)")
            }
        }
        expect(!resolvedAddSites.isEmpty && rawAddSites.isEmpty,
               "every value the picker adds is one the support enum resolved: \(rawAddSites)")

        // A list row's location caption is what tells path identities apart —
        // every bundled runtime displays as "java" (issue #1009) — and sibling
        // runtimes differ only after a long shared directory prefix, so the
        // caption must truncate from the HEAD: cutting the middle or tail
        // would hide the one component that differs. AppBundleList is not
        // compiled into this binary, so the shape is pinned here.
        var locationSites: [Int] = []
        var headTruncationSites: [Int] = []
        for (index, line) in pickerLines.enumerated()
        where !line.trimmingCharacters(in: .whitespaces).hasPrefix("//") {
            if line.contains("InstalledApps.location(for:") { locationSites.append(index + 1) }
            if line.contains(".truncationMode(.head)") { headTruncationSites.append(index + 1) }
        }
        expect(!locationSites.isEmpty && !headTruncationSites.isEmpty,
               "a path identity row shows where its file sits and truncates from the head: "
                   + "\(locationSites) \(headTruncationSites)")

        var resolvedMatchSites: [String] = []
        var rawMatchSites: [String] = []
        let matcherLines = ((try? String(
            contentsOfFile: "Sources/Vorssaint/Services/MouseExceptions/MouseAppExceptions.swift",
            encoding: .utf8)) ?? "").components(separatedBy: "\n")
        for (index, line) in matcherLines.enumerated()
        where !line.trimmingCharacters(in: .whitespaces).hasPrefix("//")
                && line.contains("executableURL") && line.contains(".path") {
            if line.contains("MouseAppExceptionSupport.identity(")
                || (index > 0 && matcherLines[index - 1].contains("MouseAppExceptionSupport.identity(")) {
                resolvedMatchSites.append("MouseAppExceptions.swift:\(index + 1)")
            } else {
                rawMatchSites.append("MouseAppExceptions.swift:\(index + 1)")
            }
        }
        expect(resolvedMatchSites.count == 1 && rawMatchSites.isEmpty,
               "the taps read an executable path only through the support enum: "
                   + "\(resolvedMatchSites) \(rawMatchSites)")
        let matcherBody = matcherLines
            .filter { !$0.trimmingCharacters(in: .whitespaces).hasPrefix("//") }
            .joined(separator: "\n")
        expect(!matcherBody.isEmpty && !matcherBody.contains("trimmingCharacters"),
               "the exception list is sanitized through the one sanitizer, never beside it")

        // The leading-slash test IS the rule that tells a stored path from a
        // bundle identifier. A second spelling of it drifts the day the rule
        // learns a new shape — a ~ path, a file URL — so every file that
        // handles an identity asks isExecutablePathIdentity instead of
        // re-testing the prefix.
        var slashRuleSites: [String] = []
        for file in ["Services/MouseExceptions/MouseAppExceptionSupport.swift",
                     "Services/InstalledApps.swift",
                     "Core/Defaults.swift"] {
            let ruleLines = ((try? String(contentsOfFile: "Sources/Vorssaint/\(file)",
                                          encoding: .utf8)) ?? "").components(separatedBy: "\n")
            if ruleLines.count <= 1 { slashRuleSites.append("\(file) unreadable") }
            for (index, line) in ruleLines.enumerated()
            where !line.trimmingCharacters(in: .whitespaces).hasPrefix("//")
                    && line.contains("hasPrefix(\"/\")") {
                slashRuleSites.append("\(file):\(index + 1)")
            }
        }
        expect(slashRuleSites.count == 1
                && slashRuleSites[0].hasPrefix("Services/MouseExceptions/MouseAppExceptionSupport.swift:"),
               "the leading-slash rule is spelled once, inside isExecutablePathIdentity: \(slashRuleSites)")
        expect(MouseAppExceptionSupport.sourceProcessID(42) == 42
                && MouseAppExceptionSupport.sourceProcessID(0) == nil
                && MouseAppExceptionSupport.sourceProcessID(-1) == nil
                && MouseAppExceptionSupport.sourceProcessID(Int64(Int32.max) + 1) == nil,
               "only positive process ids supported by the workspace enter source tracking")

        let pointer = CGPoint(x: 100, y: 100)
        let ownWindow = MouseAppExceptionSupport.Window(
            frame: CGRect(x: 0, y: 0, width: 400, height: 400), layer: 0, processID: 9)
        let systemWindow = MouseAppExceptionSupport.Window(
            frame: CGRect(x: 0, y: 0, width: 400, height: 400), layer: 25, processID: 3)
        let hiddenWindow = MouseAppExceptionSupport.Window(
            frame: CGRect(x: 0, y: 0, width: 400, height: 400), layer: 0, alpha: 0, processID: 4)
        let frontWindow = MouseAppExceptionSupport.Window(
            frame: CGRect(x: 50, y: 50, width: 300, height: 300), layer: 0, processID: 5)
        let panelWindow = MouseAppExceptionSupport.Window(
            frame: CGRect(x: 60, y: 60, width: 100, height: 100), layer: 3, processID: 6)
        let behindWindow = MouseAppExceptionSupport.Window(
            frame: CGRect(x: 0, y: 0, width: 400, height: 400), layer: 0, processID: 7)
        let underlayWindow = MouseAppExceptionSupport.Window(
            frame: CGRect(x: 0, y: 0, width: 400, height: 400), layer: -2_147_483_601, processID: 8)
        expect(MouseAppExceptionSupport.pointerWindow(
                in: [ownWindow, systemWindow, hiddenWindow, frontWindow, behindWindow],
                at: pointer, ownProcessID: 9) == frontWindow,
               "the pointer's window is the frontmost real window under it")
        expect(MouseAppExceptionSupport.pointerWindow(
                in: [underlayWindow], at: pointer, ownProcessID: 9) == nil,
               "a window living below every real one never answers for the pointer")
        expect(MouseAppExceptionSupport.pointerWindow(
                in: [panelWindow, frontWindow], at: pointer, ownProcessID: 9) == panelWindow,
               "an app's floating panel answers for its app")
        expect(MouseAppExceptionSupport.pointerWindow(
                in: [frontWindow], at: CGPoint(x: 380, y: 380), ownProcessID: 9) == nil,
               "a pointer outside every window resolves to nothing")

        expect(MouseAppExceptionSupport.cacheHolds(region: frontWindow.frame, resolvedPoint: pointer,
                                                   resolvedAt: 10, point: CGPoint(x: 120, y: 120), now: 10.2),
               "a fresh answer keeps serving while the pointer stays inside its window")
        expect(!MouseAppExceptionSupport.cacheHolds(region: frontWindow.frame, resolvedPoint: pointer,
                                                    resolvedAt: 10, point: CGPoint(x: 380, y: 380), now: 10.2),
               "the pointer leaving the window asks the window server again")
        expect(!MouseAppExceptionSupport.cacheHolds(region: frontWindow.frame, resolvedPoint: pointer,
                                                    resolvedAt: 10, point: pointer,
                                                    now: 10 + MouseAppExceptionSupport.resolveLifetime),
               "an answer expires, so a window that opened under a resting pointer is noticed")
        expect(MouseAppExceptionSupport.cacheHolds(region: nil, resolvedPoint: pointer,
                                                   resolvedAt: 10, point: pointer, now: 10.2)
                && !MouseAppExceptionSupport.cacheHolds(region: nil, resolvedPoint: pointer,
                                                        resolvedAt: 10,
                                                        point: CGPoint(x: 101, y: 100), now: 10.2),
               "an answer of nothing only covers the exact spot it was resolved at")

        for language in AppLanguage.allCases {
            let strings = FeatureStrings.mouseExceptions(language)
            let values = Mirror(reflecting: strings).children.compactMap { $0.value as? String }
            expect(!values.isEmpty && values.allSatisfy { !$0.isEmpty },
                   "every mouse exception string is set for \(language.rawValue)")
            expect(values.allSatisfy { !$0.contains("—") },
                   "no em-dash in visible mouse exception strings (\(language.rawValue))")
            expect(Set(MouseExceptionScope.allCases.map { strings.caption(for: $0) }).count
                    == MouseExceptionScope.allCases.count,
                   "each list explains its own feature, never the same line twice (\(language.rawValue))")
        }

        for language in AppLanguage.allCases {
            let strings = FeatureStrings.clipboardIgnoredApps(language)
            let values = Mirror(reflecting: strings).children.compactMap { $0.value as? String }
            expect(values.count == 4 && values.allSatisfy { !$0.isEmpty },
                   "every clipboard skip list string is set for \(language.rawValue)")
            expect(values.allSatisfy { !$0.contains("—") },
                   "no em-dash in visible clipboard skip list strings (\(language.rawValue))")
        }

        for language in AppLanguage.allCases {
            let strings = FeatureStrings.switcherAppRules(language)
            let values = Mirror(reflecting: strings).children.compactMap { $0.value as? String }
            expect(values.count == 8 && values.allSatisfy { !$0.isEmpty },
                   "every per-app switcher rule string is set for \(language.rawValue)")
            expect(values.allSatisfy { !$0.contains("—") },
                   "no em-dash in per-app switcher rule strings (\(language.rawValue))")
            expect(Set([strings.showWithoutWindows, strings.windowsOnly, strings.hidden]).count == 3,
                   "each per-app switcher choice is distinct for \(language.rawValue)")
        }

        expect(FinderRenameSupport.acceptsFocusedRole("AXOutline")
                && !FinderRenameSupport.acceptsFocusedRole("AXTextField")
                && !FinderRenameSupport.acceptsFocusedRole("AXTextArea")
                && !FinderRenameSupport.acceptsFocusedRole(nil),
               "Finder rename only acts outside editable fields with a known focus")

        for language in AppLanguage.allCases {
            let strings = FeatureStrings.windowPreviewExclusions(language)
            let values = Mirror(reflecting: strings).children.compactMap { $0.value as? String }
            expect(values.count == 5 && values.allSatisfy { !$0.isEmpty },
                   "every window preview exclusion string is set for \(language.rawValue)")
            expect(values.allSatisfy { !$0.contains("—") },
                   "no em-dash in visible window preview exclusion strings (\(language.rawValue))")
        }

        for language in AppLanguage.allCases {
            let strings = FeatureStrings.diskExclusions(language)
            let values = Mirror(reflecting: strings).children.compactMap { $0.value as? String }
            expect(values.count == 6 && values.allSatisfy { !$0.isEmpty },
                   "every disk exclusion string is set for \(language.rawValue)")
            expect(values.allSatisfy { !$0.contains("—") },
                   "no em-dash in visible disk exclusion strings (\(language.rawValue))")
        }

        for language in AppLanguage.allCases {
            let strings = WindowDirectionalStrings.localized(language)
            let values = Mirror(reflecting: strings).children.compactMap { $0.value as? String }
            expect(values.count == 2 && values.allSatisfy { !$0.isEmpty },
                   "every directional layout string is set for \(language.rawValue)")
            expect(values.allSatisfy { !$0.contains("—") },
                   "no em-dash in directional layout strings (\(language.rawValue))")
        }

        // MARK: Settings backup

        let backupKeys = SettingsBackupSupport.exportKeys()
        expect(backupKeys.contains(DefaultsKey.switcherEnabled)
                && backupKeys.contains(DefaultsKey.menuBarCPU)
                && backupKeys.contains(DefaultsKey.language)
                && backupKeys.contains(DefaultsKey.appVolumes)
                && backupKeys.contains(DefaultsKey.mixerShowFinder)
                && backupKeys.contains(DefaultsKey.mixerHideInactiveApps)
                && backupKeys.contains(DefaultsKey.keepAwakeActiveIcon)
                && backupKeys.contains(AppFeature.dockPreview.availabilityKey),
               "backup carries preferences, menu bar pins, Keep Awake appearance, language and hub availability")
        expect(backupKeys.contains(DefaultsKey.launchAtLoginWanted),
               "the launch at login choice travels with the settings backup")
        expect(backupKeys.contains(DefaultsKey.appearance),
               "the light or dark choice travels with the settings backup")
        expect(Set([
            DefaultsKey.mediaImageResizeKind,
            DefaultsKey.mediaImageResizeWidth,
            DefaultsKey.mediaImageResizeHeight,
            DefaultsKey.mediaImageExactResizeMode,
            DefaultsKey.mediaImageWatermarkKind,
            DefaultsKey.mediaImageWatermarkText,
            DefaultsKey.mediaImageWatermarkPosition,
            DefaultsKey.mediaImageWatermarkOpacity,
