        expect(backupKeys.contains(DefaultsKey.panelShowFanControl)
                && backupKeys.contains(DefaultsKey.fanControlMode)
                && backupKeys.contains(DefaultsKey.fanControlCoolingLevel)
                && backupKeys.contains(DefaultsKey.fanControlCurves)
                && backupKeys.contains(DefaultsKey.menuBarFanSpeed)
                && !backupKeys.contains(DefaultsKey.fanControlRecoveryNeeded)
                && !backupKeys.contains(DefaultsKey.fanControlHelperVersion),
               "fan display and cooling preferences travel while helper recovery state stays on one Mac")
        expect(backupKeys.contains(DefaultsKey.screenshotSharingEnabled),
               "the temporary screenshot links preference travels with settings backup")
        expect(!backupKeys.contains(DefaultsKey.clipboardHistoryEntries)
                && !backupKeys.contains(DefaultsKey.shelfItems)
                && !backupKeys.contains(DefaultsKey.sleepDisabledFlag)
                && !backupKeys.contains(DefaultsKey.micMuteActive)
                && !backupKeys.contains(DefaultsKey.micMuteSavedVolumes)
                && !backupKeys.contains(DefaultsKey.micMuteMutedDevices)
                && !backupKeys.contains(DefaultsKey.cleanerLastAutoRun)
                && !backupKeys.contains(DefaultsKey.statusItemPlacementGeneration)
                && !backupKeys.contains(DefaultsKey.displaysSwitchedOff)
                && !backupKeys.contains(DefaultsKey.screenshotSharingDeveloperEndpoint),
               "backup never carries private content, live state or machine markers")
        expect(Defaults.registeredDefaults[DefaultsKey.displaysSwitchedOff] == nil,
               "a display switched off is a repair note for this machine, not a setting")
        expect(Defaults.registeredDefaults[DefaultsKey.startupDidNotFinish] == nil,
               "a start that did not finish is a note for this machine, not a setting")

        // A stored shortcut is text on disk and can arrive edited or through
        // an imported settings file, so the number is checked before it ever
        // reaches an API that takes a narrower type.
        expect(GlobalShortcut(storageValue: "command:-1") == nil,
               "a negative key code never becomes a shortcut")
        expect(GlobalShortcut(storageValue: "command:99999999") == nil,
               "a key code past the end of the range never becomes a shortcut")
        expect(GlobalShortcut(storageValue: "command:\(Int64.min)") == nil,
               "the smallest possible number never becomes a shortcut")
        expect(!GlobalShortcut(keyCode: -1, modifiers: [.command]).isValid
                && !GlobalShortcut(keyCode: 70000, modifiers: [.command]).isValid,
               "a shortcut built with a number out of range is not valid")
        expect(GlobalShortcut(keyCode: -1, modifiers: [.command]).carbonKeyCode == 0,
               "a number out of range converts to nothing instead of trapping")
        expect(GlobalShortcut(storageValue: "control+option+command:40") != nil,
               "an ordinary stored shortcut still reads back")
        expect(!backupKeys.contains(DefaultsKey.startupDidNotFinish),
               "the backup never carries a note about a start that did not finish")
        expect(backupKeys.contains(DefaultsKey.hasOnboarded)
                && backupKeys.contains(DefaultsKey.featuresOnboardingVersion)
                && backupKeys.contains(DefaultsKey.lastUpdateIntroVersion),
               "a restored Mac does not replay onboarding or the intros already seen")
        let backupPayload = SettingsBackupSupport.payload(appVersion: "test") { key in
            key == DefaultsKey.switcherEnabled ? true : nil
        }
        expect(backupPayload[SettingsBackupSupport.formatVersionKey] as? Int
                == SettingsBackupSupport.formatVersion,
               "backup envelope carries the format version")
        let roundTrip = SettingsBackupSupport.sanitizedSettings(from: backupPayload)
        expect(roundTrip?[DefaultsKey.switcherEnabled] as? Bool == true,
               "a backup round-trips its settings")
        var logoProfileOptions = profileOptions
        logoProfileOptions.watermark = MediaImageWatermark(kind: .textAndLogo,
                                                           text: "Portable",
                                                           logoPath: "/Users/private/Brand.png")
        let logoProfilesRaw = String(data: try! JSONEncoder().encode([
            MediaImageProfile(id: "logo", name: "Logo", options: logoProfileOptions),
        ]), encoding: .utf8)!
        let portableMediaBackup = SettingsBackupSupport.payload(appVersion: "test") { key in
            switch key {
            case DefaultsKey.mediaImageWatermarkLogoPath: return "/Users/private/Brand.png"
            case DefaultsKey.mediaImageWatermarkKind: return MediaImageWatermarkKind.textAndLogo.rawValue
            case DefaultsKey.mediaImageWatermarkText: return "Portable"
            case DefaultsKey.mediaImageProfiles: return logoProfilesRaw
            default: return nil
            }
        }
        let portableMediaSettings = SettingsBackupSupport.sanitizedSettings(from: portableMediaBackup)
        let portableProfiles = (portableMediaSettings?[DefaultsKey.mediaImageProfiles] as? String)
            .flatMap { $0.data(using: .utf8) }
            .flatMap { try? JSONDecoder().decode([MediaImageProfile].self, from: $0) }
        expect(portableMediaSettings?[DefaultsKey.mediaImageWatermarkLogoPath] == nil
               && portableMediaSettings?[DefaultsKey.mediaImageWatermarkKind] as? String
                    == MediaImageWatermarkKind.text.rawValue
               && portableProfiles?.first?.options.watermark.logoPath.isEmpty == true
               && portableProfiles?.first?.options.watermark.kind == .text,
               "media backups remove local logo paths while preserving portable watermark text")
        // A mouse exception list holds bundle ids and, since issue #1009, the
        // resolved path of a program that has none. The path carries the short
        // username and names nothing on another Mac, and `valueLooksRight`
        // cannot see it: ["com.apple.Safari", "/Users/.../java"] is a perfectly
        // good [String]. Driven from allCases, so a scope that renames its key
        // or two scopes that come to share one stay covered.
        let localJavaPath = "/Users/josh/Library/Application Support/PrismLauncher"
            + "/java/jre-legacy/zulu-8.jre/Contents/Home/bin/java"
        let exceptionKeys = Set(MouseExceptionScope.allCases.map(\.defaultsKey))
        let mixedExceptionBackup = SettingsBackupSupport.payload(appVersion: "test") { key in
            exceptionKeys.contains(key) ? ["com.apple.Safari", localJavaPath] : nil
        }
        let exportedExceptions = mixedExceptionBackup[SettingsBackupSupport.settingsKey] as? [String: Any]
        expect(!exceptionKeys.isEmpty
                && exceptionKeys.allSatisfy { exportedExceptions?[$0] as? [String] == ["com.apple.Safari"] },
               "every mouse exception list exports its bundle ids and drops the machine-local paths")
        let handEditedExceptions = SettingsBackupSupport.sanitizedSettings(from: [
            SettingsBackupSupport.formatVersionKey: SettingsBackupSupport.formatVersion,
            SettingsBackupSupport.settingsKey: Dictionary(uniqueKeysWithValues:
                exceptionKeys.map { ($0, ["com.apple.Safari", localJavaPath] as Any) }),
        ])
        expect(exceptionKeys.allSatisfy {
                    handEditedExceptions?[$0] as? [String] == ["com.apple.Safari"]
               },
               "a hand-edited backup cannot restore a machine-local path into an exception list")
        // The complement, so the filter cannot be mutated into dropping the
        // whole list and stay green.
        let bundleOnlyBackup = SettingsBackupSupport.payload(appVersion: "test") { key in
            key == MouseExceptionScope.smoothScroll.defaultsKey
                ? ["com.apple.Safari", "com.apple.Terminal"] : nil
        }
        expect((bundleOnlyBackup[SettingsBackupSupport.settingsKey] as? [String: Any])?[
                    MouseExceptionScope.smoothScroll.defaultsKey] as? [String]
                    == ["com.apple.Safari", "com.apple.Terminal"],
               "an exception list of only bundle ids survives a backup unchanged")
        // Filtering the export is only half the job: applying a backup clears
        // every exported key before writing the file's values, and the file no
        // longer carries the path half -- so a restore would delete those
        // entries, including on the Mac the backup came from. The two halves
        // of carrying them across are pure, so they are asserted directly.
        expect(SettingsBackupSupport.pathIdentities(
                    in: ["com.apple.Safari", localJavaPath, "com.apple.Terminal"]) == [localJavaPath],
               "only the machine-local paths are carried across a settings restore")
        expect(SettingsBackupSupport.restoredExceptionList(
                    restored: ["com.apple.Safari"], carried: [localJavaPath])
                    == ["com.apple.Safari", localJavaPath],
               "a restore puts the machine-local entries back beside the restored bundle ids")
        expect(SettingsBackupSupport.restoredExceptionList(
                    restored: ["com.apple.Safari", localJavaPath], carried: [localJavaPath])
                    == ["com.apple.Safari", localJavaPath],
               "applying the same backup twice does not double a carried path")
        // SettingsBackup.swift is not in the test binary, and the fix is an
        // ORDER: capture before the clear, put back after the write. Either
        // one moved leaves the code present and the entries still deleted.
        // Strip comments before asserting: "X appears before Y" would otherwise
        // be satisfied by a doc comment mentioning either.
        let isCodeLine: (String) -> Bool = {
            !$0.trimmingCharacters(in: .whitespaces).hasPrefix("//")
        }
        let backupServiceLines = ((try? String(
            contentsOfFile: "Sources/Vorssaint/Services/SettingsBackup.swift",
            encoding: .utf8)) ?? "").components(separatedBy: "\n")
        let captureAt = backupServiceLines.firstIndex {
            isCodeLine($0) && $0.contains("SettingsBackupSupport.pathIdentities(")
        }
        let clearAt = backupServiceLines.firstIndex {
            isCodeLine($0) && $0.contains("defaults.removeObject(forKey: key)")
        }
        let putBackAt = backupServiceLines.firstIndex {
            isCodeLine($0) && $0.contains("SettingsBackupSupport.restoredExceptionList(")
        }
        let writeAt = backupServiceLines.firstIndex {
            isCodeLine($0) && $0.contains("defaults.set(value, forKey: key)")
        }
        expect([captureAt, clearAt, putBackAt, writeAt].allSatisfy { $0 != nil }
                && captureAt! < clearAt! && writeAt! < putBackAt!,
               "a settings restore reads the machine-local entries before clearing "
                   + "and writes them back after the file's values")
        expect(SettingsBackupSupport.sanitizedSettings(from: [SettingsBackupSupport.settingsKey: [String: Any]()]) == nil,
               "a file without the version envelope is rejected")
        let tampered: [String: Any] = [
            SettingsBackupSupport.formatVersionKey: 1,
            SettingsBackupSupport.settingsKey: ["evilKey": "x", DefaultsKey.autoQuitEnabled: true] as [String: Any],
        ]
        let filteredImport = SettingsBackupSupport.sanitizedSettings(from: tampered)
        expect(filteredImport?["evilKey"] == nil
                && filteredImport?[DefaultsKey.autoQuitEnabled] as? Bool == true,
               "unknown keys are dropped on import")
        expect(SettingsBackupSupport.sanitizedSettings(from: [
            SettingsBackupSupport.formatVersionKey: 99,
            SettingsBackupSupport.settingsKey: [String: Any](),
        ]) == nil, "a future format version is rejected")
        expect(SettingsBackupSupport.formatVersion(from: [SettingsBackupSupport.formatVersionKey: 1]) == 1
                && SettingsBackupSupport.formatVersion(from: [SettingsBackupSupport.formatVersionKey: NSNumber(value: 1)]) == 1
                && SettingsBackupSupport.formatVersion(from: [SettingsBackupSupport.formatVersionKey: "1"]) == 1
                && SettingsBackupSupport.formatVersion(from: [SettingsBackupSupport.formatVersionKey: " 1 \n"]) == 1
                && SettingsBackupSupport.formatVersion(from: [SettingsBackupSupport.formatVersionKey: "invalid"]) == nil,
               "backup format version accepts integer, NSNumber and string representations")
        let stringVersionBackup: [String: Any] = [
            SettingsBackupSupport.formatVersionKey: "1",
            SettingsBackupSupport.settingsKey: [
                DefaultsKey.smoothScrollStep: 60,
            ] as [String: Any],
        ]
        expect(SettingsBackupSupport.sanitizedSettings(from: stringVersionBackup)?[DefaultsKey.smoothScrollStep] as? Int == 60,
               "a backup with a string-encoded format version restores correctly")

        // A backup file can be edited by hand, and a value of the wrong shape
        // would reach code that trusts its own settings.
        let wrongShapes: [String: Any] = [
            SettingsBackupSupport.formatVersionKey: 1,
            SettingsBackupSupport.settingsKey: [
                DefaultsKey.smoothScrollEnabled: "yes please",
                DefaultsKey.monitorInterval: "soon",
                DefaultsKey.smoothScrollStep: 60,
                DefaultsKey.switcherAppRules: "not a rule dictionary",
            ] as [String: Any],
        ]
        let shapeChecked = SettingsBackupSupport.sanitizedSettings(from: wrongShapes)
        expect(shapeChecked?[DefaultsKey.smoothScrollEnabled] == nil,
               "text where a switch belongs is dropped on import")
        expect(shapeChecked?[DefaultsKey.monitorInterval] == nil,
               "text where a number belongs is dropped on import")
        expect(shapeChecked?[DefaultsKey.switcherAppRules] == nil,
               "text where a per-app rule dictionary belongs is dropped on import")
        expect(shapeChecked?[DefaultsKey.smoothScrollStep] as? Int == 60,
               "a value of the right shape still restores")
        let bridgedInput: [String: Any] = [
            SettingsBackupSupport.formatVersionKey: 1,
            SettingsBackupSupport.settingsKey: [
                DefaultsKey.switcherEnabled: 1,
                DefaultsKey.monitorInterval: true,
                DefaultsKey.dockPreviewBackgroundOpacity: true,
                DefaultsKey.smoothScrollStep: 60,
                DefaultsKey.scratchpadBackgroundOpacity: 0.5,
                DefaultsKey.smoothScrollExceptions: [1],
                DefaultsKey.autoQuitExceptions: ["com.example.editor"],
                DefaultsKey.switcherAppRules: ["com.example.editor": 1],
                DefaultsKey.mouseButtonShortcuts: ["4": "command:0"],
            ] as [String: Any],
        ]
        var bridgedSettings: [String: Any]?
        if let data = try? PropertyListSerialization.data(fromPropertyList: bridgedInput,
                                                          format: .binary,
                                                          options: 0),
           let parsed = try? PropertyListSerialization.propertyList(from: data,
                                                                     options: [],
                                                                     format: nil),
           let payload = parsed as? [String: Any] {
            bridgedSettings = SettingsBackupSupport.sanitizedSettings(from: payload)
        }
        expect(bridgedSettings?[DefaultsKey.switcherEnabled] == nil
                && bridgedSettings?[DefaultsKey.monitorInterval] == nil
                && bridgedSettings?[DefaultsKey.dockPreviewBackgroundOpacity] == nil,
               "property-list numbers and booleans do not cross scalar setting types")
        expect(bridgedSettings?[DefaultsKey.smoothScrollExceptions] == nil
                && bridgedSettings?[DefaultsKey.switcherAppRules] == nil,
               "wrong collection element types are dropped on import")
        expect(bridgedSettings?[DefaultsKey.smoothScrollStep] as? Int == 60
                && bridgedSettings?[DefaultsKey.scratchpadBackgroundOpacity] as? Double == 0.5
                && bridgedSettings?[DefaultsKey.autoQuitExceptions] as? [String]
                    == ["com.example.editor"]
                && bridgedSettings?[DefaultsKey.mouseButtonShortcuts] as? [String: String]
                    == ["4": "command:0"],
               "property-list values of the declared scalar and collection types still restore")
        let switcherRulesBackup: [String: Any] = [
            SettingsBackupSupport.formatVersionKey: 1,
            SettingsBackupSupport.settingsKey: [
                DefaultsKey.switcherAppRules: [
                    "com.example.editor": SwitcherAppRule.windowsOnly.rawValue,
                ] as [String: Any],
            ] as [String: Any],
        ]
        let restoredSwitcherRules = SettingsBackupSupport.sanitizedSettings(from: switcherRulesBackup)?[
            DefaultsKey.switcherAppRules
        ] as? [String: Any]
        expect(restoredSwitcherRules?["com.example.editor"] as? String
                == SwitcherAppRule.windowsOnly.rawValue,
               "per-app Switcher rules keep their bundle identity and behavior through backup import")
        expect(Defaults.registeredDefaults[DefaultsKey.preciseVolumeRollerEnabled] as? Bool == false,
               "precise volume roller is opt-in")

        // MARK: Precise volume roller

        var volumeGate = PreciseVolumeRollerGate()
        expect(volumeGate.accepts(.up, at: 100.00),
               "precise volume accepts the first wheel step")
        expect(!volumeGate.accepts(.up, at: 100.01),
               "precise volume drops repeats that arrive inside the spacing window")
        expect(volumeGate.accepts(.up, at: 100.05),
               "precise volume accepts a later step in the same direction")

        var reversalGate = PreciseVolumeRollerGate()
        expect(reversalGate.accepts(.up, at: 200.00),
               "precise volume reversal setup accepts the initial direction")
        expect(!reversalGate.accepts(.down, at: 200.08),
               "precise volume ignores the first opposite pulse inside the reversal window")
        expect(!reversalGate.accepts(.down, at: 200.16),
               "precise volume waits for a stable opposite direction")
        expect(reversalGate.accepts(.down, at: 200.24),
               "precise volume accepts the confirmed opposite direction")

        var oldDirectionGate = PreciseVolumeRollerGate()
        expect(oldDirectionGate.accepts(.up, at: 300.00),
               "precise volume accepts first old-direction step")
        expect(oldDirectionGate.accepts(.down, at: 300.40),
               "precise volume accepts an opposite step after the reversal window")
        var fastStreamGate = PreciseVolumeRollerGate()
        let fastAccepted = stride(from: 400.00, through: 400.10, by: 0.02)
            .filter { fastStreamGate.accepts(.up, at: $0) }
        expect(fastAccepted.count == 3,
               "precise volume rate-limits sustained fast input instead of starving it")
        expect(PreciseVolumeMediaKey.volumeUp.rollerDirection == .up
                && PreciseVolumeMediaKey.volumeDown.rollerDirection == .down
                && PreciseVolumeMediaKey.mute.rollerDirection == nil,
               "precise volume only remaps volume up and down media keys")

        // MARK: App updates

        expect(AppUpdatesSupport.compare("1.130.0", "1.129.0") == .orderedDescending
                && AppUpdatesSupport.compare("0.730.0.7300790", "0.731.0") == .orderedAscending
                && AppUpdatesSupport.compare("26.084.0504", "26.119.0622.0003") == .orderedAscending,
               "versions compare part by part, as numbers")
        expect(AppUpdatesSupport.compare("1.2", "1.2.0") == .orderedSame
                && AppUpdatesSupport.compare("1.2", "1.2.1") == .orderedAscending
                && AppUpdatesSupport.compare("3.5.230", "3.5.230") == .orderedSame,
               "a missing part counts as zero")
        expect(AppUpdatesSupport.compare("2026.723.1724", "2026.714.1952") == .orderedDescending
                && AppUpdatesSupport.compare("00123", "123") == .orderedSame,
               "leading zeros never decide a comparison")
        expect(!AppUpdatesSupport.isNewer("1.9a", than: "1.10")
                && AppUpdatesSupport.isNewer("1.10", than: "1.9a")
                && !AppUpdatesSupport.isNewer("3.5beta", than: "3.5")
                && AppUpdatesSupport.isNewer("3.5", than: "3.5beta")
                && AppUpdatesSupport.isNewer("1.9b", than: "1.9a"),
               "a lettered part compares by its number first, and the bare number outranks its own suffixed run")
        expect(AppUpdatesSupport.versionCore("3.5.262,260717dcrpwg7m0") == "3.5.262"
                && AppUpdatesSupport.versionCore("0.0.402") == "0.0.402",
               "the revision after a comma is not part of the version")
        expect(AppUpdatesSupport.isNewer("3.5.262,260717dcrpwg7m0", than: "3.5.230")
                && !AppUpdatesSupport.isNewer("1.130.0", than: "1.130.0"),
               "an update is only newer when the number really grew")
        expect(AppUpdatesSupport.isUncomparable("latest") && AppUpdatesSupport.isUncomparable("")
                && !AppUpdatesSupport.isUncomparable("1.0"),
               "a package without a version number cannot be judged")

        func caskUpdate(_ token: String, installed: String, current: String,
                        pinned: Bool = false) -> HomebrewPackageUpdate {
            HomebrewPackageUpdate(kind: .cask, name: token, installedVersions: [installed],
                                  currentVersion: current, isPinned: pinned)
        }
        let caskRecords = [
            HomebrewCaskRecord(token: "editor", displayName: "Editor",
                               installedVersion: "1.129.0", appFileNames: ["Editor.app"]),
            HomebrewCaskRecord(token: "chat", displayName: "Chat",
                               installedVersion: "0.0.374", appFileNames: ["Chat.app"]),
            HomebrewCaskRecord(token: "installer", displayName: "Installer",
                               installedVersion: "26.078", appFileNames: []),
        ]
        // The receipt says 1.129 while the app on disk already updated itself
        // to 1.130: believing the receipt would offer an update that happened.
        let packageApps = [
            AppUpdatesSupport.InstalledApp(name: "Editor", bundleID: "com.vendor.editor",
                                           path: "/Applications/Editor.app", version: "1.130.0",
                                           isFromAppStore: false),
            AppUpdatesSupport.InstalledApp(name: "Chat", bundleID: "com.vendor.chat",
                                           path: "/Applications/Chat.app", version: "0.0.401",
                                           isFromAppStore: false),
        ]
        let packageRows = AppUpdatesSupport.packageUpdates(
            outdated: [caskUpdate("editor", installed: "1.129.0", current: "1.130.0"),
                       caskUpdate("chat", installed: "0.0.374", current: "0.0.402"),
                       caskUpdate("installer", installed: "26.078", current: "26.119"),
                       caskUpdate("pinnedApp", installed: "1.0", current: "2.0", pinned: true),
                       caskUpdate("rolling", installed: "latest", current: "latest")],
            installed: caskRecords,
            apps: packageApps)
        expect(!packageRows.contains { $0.token == "editor" },
               "an app that already updated itself is not offered again")
        expect(packageRows.contains { $0.token == "chat" && $0.installedVersion == "0.0.401" },
               "the version the app reports wins over the package receipt")
        expect(!packageRows.contains { $0.token == "installer" },
               "a package record without an app bundle is not presented as an installed app")
        // Packages that install through an installer declare no app, so the
        // catalog name is tried as a bundle name before giving up.
        let namedRows = AppUpdatesSupport.packageUpdates(
            outdated: [caskUpdate("installer", installed: "26.078", current: "26.119")],
            installed: caskRecords,
            apps: [AppUpdatesSupport.InstalledApp(name: "Installer", bundleID: "com.vendor.installer",
                                                  path: "/Applications/Installer.app", version: "26.084",
                                                  isFromAppStore: false)])
        expect(namedRows.first?.installedVersion == "26.084",
               "a package with no declared app is matched by its catalog name")
        let exactPathRecord = HomebrewCaskRecord(token: "editor", displayName: "Editor",
                                                 installedVersion: "1.0",
                                                 appFileNames: ["Editor.app"],
                                                 appPaths: ["/Users/test/Applications/Editor.app"])
        let duplicateNamedApps = [
            AppUpdatesSupport.InstalledApp(name: "Editor system", bundleID: "com.vendor.editor",
                                           path: "/Applications/Editor.app", version: "9.0",
                                           isFromAppStore: false),
            AppUpdatesSupport.InstalledApp(name: "Editor managed", bundleID: "com.vendor.editor",
                                           path: "/Users/test/Applications/Editor.app", version: "1.0",
                                           isFromAppStore: false),
        ]
        expect(AppUpdatesSupport.packageBundle(for: exactPathRecord,
                                               apps: duplicateNamedApps)?.version == "1.0",
               "package updates use the exact managed app path when same-named copies exist")
        expect(AppUpdatesSupport.packageBundle(for: caskRecords[0],
                                               apps: duplicateNamedApps,
                                               homeDirectory: "/Users/test") == nil,
               "a name-only package record never guesses between same-named app copies")
        let downloadOnlyCopy = AppUpdatesSupport.InstalledApp(
            name: "Editor download", bundleID: "com.vendor.editor",
            path: "/Users/test/Downloads/Editor.app", version: "1.0",
            isFromAppStore: false)
        expect(AppUpdatesSupport.packageBundle(for: caskRecords[0],
                                               apps: [downloadOnlyCopy],
                                               homeDirectory: "/Users/test") == nil,
               "a name-only package record never claims a homonymous app outside standard app folders")
        let alreadyCurrent = AppUpdatesSupport.packageUpdates(
            outdated: [caskUpdate("installer", installed: "26.078", current: "26.119")],
            installed: caskRecords,
            apps: [AppUpdatesSupport.InstalledApp(name: "Installer", bundleID: "com.vendor.installer",
                                                  path: "/Applications/Installer.app", version: "26.200",
                                                  isFromAppStore: false)])
        expect(alreadyCurrent.isEmpty,
               "the name match also suppresses an app that ran ahead of its package")
        expect(!packageRows.contains { $0.token == "pinnedApp" }
                && !packageRows.contains { $0.token == "rolling" },
               "pinned packages and packages without a version stay out")
        expect(packageRows.allSatisfy { $0.canInstallInPlace },
               "package rows can be installed on the spot")
        let ownPackageRows = AppUpdatesSupport.packageUpdates(
            outdated: [caskUpdate("vorssaint", installed: "3.1.12", current: "3.2.0")],
            installed: [],
            ignoredTokens: ["vorssaint"],
            apps: [])
        expect(ownPackageRows.isEmpty,
               "the app update list never offers to replace Vorssaint through its own package")

        let storeApps = [
            AppUpdatesSupport.InstalledApp(name: "Blocker", bundleID: "net.example.blocker",
                                           path: "/Applications/Blocker.app",
                                           version: "2026.714.1952", isFromAppStore: true),
            AppUpdatesSupport.InstalledApp(name: "Sheets", bundleID: "com.example.sheets",
                                           path: "/Applications/Sheets.app",
                                           version: "16.111.1", isFromAppStore: true),
            AppUpdatesSupport.InstalledApp(name: "Chat", bundleID: "com.example.chat",
                                           path: "/Applications/Chat.app",
                                           version: "0.0.401", isFromAppStore: false),
            AppUpdatesSupport.InstalledApp(name: "Future", bundleID: "com.example.future",
                                           path: "/Applications/Future.app",
                                           version: "1.0", isFromAppStore: true),
        ]
        let candidates = AppUpdatesSupport.appStoreCandidates(apps: storeApps,
                                                              coveredPaths: ["/Applications/Chat.app"])
        expect(candidates.count == 3 && !candidates.contains { $0.bundleID == "com.example.chat" },
               "only store purchases are asked about, and never one the package manager answers for")
        let storeVersions = [
            "net.example.blocker": AppUpdatesSupport.StoreEntry(bundleID: "net.example.blocker",
                                                                version: "2026.723.1724",
                                                                minimumOSVersion: "14.0",
                                                                page: "https://apps.apple.com/app"),
            "com.example.sheets": AppUpdatesSupport.StoreEntry(bundleID: "com.example.sheets",
                                                               version: "16.111.1",
                                                               minimumOSVersion: nil, page: nil),
            "com.example.future": AppUpdatesSupport.StoreEntry(bundleID: "com.example.future",
                                                               version: "2.0",
                                                               minimumOSVersion: "26.0", page: nil),
        ]
        let storeRows = AppUpdatesSupport.appStoreUpdates(apps: candidates,
                                                         storeVersions: storeVersions,
                                                         operatingSystemVersion: "15.7")
        expect(storeRows.count == 1 && storeRows[0].name == "Blocker"
                && !storeRows[0].canInstallInPlace,
               "a store app is listed only when its newer version runs on this macOS")

        let mergedRows = AppUpdatesSupport.merged(storeRows, packageRows)
        expect(mergedRows.count == packageRows.count + storeRows.count
                && mergedRows.first?.canInstallInPlace == true
                && mergedRows.last?.canInstallInPlace == false,
               "the merged list puts what can be updated here first")
        let everything = Set(mergedRows.map(\.id))
        expect(AppUpdatesSupport.tokens(in: mergedRows, selection: everything).count == packageRows.count
                && AppUpdatesSupport.hasStoreSelection(in: mergedRows, selection: everything),
               "the selection splits into package tokens and store hand-offs")
        expect(AppUpdatesSupport.tokens(in: mergedRows, selection: []).isEmpty
                && !AppUpdatesSupport.hasStoreSelection(in: mergedRows, selection: []),
               "an empty selection asks for nothing")
        expect(AppUpdatesSupport.singleStorePage(in: mergedRows, selection: everything)
                == "https://apps.apple.com/app",
               "one ticked store row hands off to its own page, where its own button goes")
        let secondStoreRow = AppUpdatesSupport.Item(id: "store:com.example.notes",
                                                    source: .appStore,
                                                    name: "Notes",
                                                    installedVersion: "1.0",
                                                    latestVersion: "2.0",
                                                    token: nil,
                                                    bundlePath: nil,
                                                    storePage: "https://apps.apple.com/notes")
        let twoStoreRows = mergedRows + [secondStoreRow]
        expect(AppUpdatesSupport.singleStorePage(in: twoStoreRows,
                                                 selection: Set(twoStoreRows.map(\.id))) == nil
                && AppUpdatesSupport.singleStorePage(in: mergedRows, selection: []) == nil,
               "two store rows, or none, have no single page to land on")

        let keptSelection = AppUpdatesSupport.reconciledSelection(
            previous: [mergedRows[0].id, "gone:row"],
            knownIDs: Set(mergedRows.map(\.id)),
            items: mergedRows)
        expect(keptSelection == [mergedRows[0].id],
               "a row that disappeared leaves the selection behind")
        let withNewFinding = AppUpdatesSupport.reconciledSelection(
            previous: [], knownIDs: [], items: mergedRows)
        expect(withNewFinding == Set(mergedRows.map(\.id)),
               "findings the person has not seen yet arrive already ticked")

        expect(AppUpdatesSupport.storeLookupURL(bundleIDs: [], country: "BR") == nil,
               "no identifiers means no request")
        let lookup = AppUpdatesSupport.storeLookupURL(bundleIDs: ["a.b", "c.d"], country: "BR")?
            .absoluteString ?? ""
        expect(lookup.contains("bundleId=a.b,c.d") && lookup.contains("country=BR")
                && lookup.contains("entity=macSoftware"),
               "several apps are asked about in one request")
        let noCountry = AppUpdatesSupport.storeLookupURL(bundleIDs: ["a.b"], country: nil)?
            .absoluteString ?? ""
        expect(!noCountry.contains("country="), "without a region the request carries none")
        let lookupBody = Data(#"{"resultCount":2,"results":[{"kind":"mac-software","bundleId":"a.b","version":"2.0","minimumOsVersion":"15.0","trackViewUrl":"https://x"},{"kind":"software","bundleId":"c.d","version":"9.0","minimumOsVersion":"12.0"}]}"#.utf8)
        let lookupEntries = AppUpdatesSupport.parseStoreLookup(lookupBody)
        let lookupEntry = lookupEntries["a.b"]
        expect(lookupEntry?.version == "2.0" && lookupEntry?.minimumOSVersion == "15.0",
               "the store answer is read back")
        expect(lookupEntries["c.d"] == nil,
               "another platform's listing is not the installed Mac app's version")
        expect(AppUpdatesSupport.parseStoreLookup(Data("not json".utf8)).isEmpty,
               "a broken store answer yields nothing instead of throwing")

        let onlineCatalogBody = Data(#"""
        [
          {"token":"notes-stable","version":"2.0,revision","artifacts":[{"uninstall":[{"quit":"com.example.notes"}]},{"app":["Notes.app"],"target":"/Applications/Notes.app"}],"depends_on":{"macos":{">=":["14"]}}},
          {"token":"notes-preview","version":"3.0","artifacts":[{"uninstall":[{"quit":["com.example.notes.preview"]}]},{"app":["Notes.app"]}],"depends_on":{"macos":{">=":["14"]}}},
          {"token":"writer","version":"2.0","artifacts":[{"app":["Writer Source.app",{"target":"Writer.app"}],"target":"/Applications/Writer.app"}]},
          {"token":"duplicate-one","version":"2.0","artifacts":[{"uninstall":[{"quit":"com.example.one"}]},{"app":["Duplicate.app"]}]},
          {"token":"duplicate-two","version":"2.0","artifacts":[{"uninstall":[{"quit":"com.example.two"}]},{"app":["Duplicate.app"]}]},
          {"token":"future","version":"4.0","artifacts":[{"app":["Future.app"]}],"depends_on":{"macos":{">=":["26"]}}},
          {"token":"exact","version":"5.0","artifacts":[{"app":["Exact.app"]}],"depends_on":{"macos":{"==":["15"]}}},
          {"token":"rolling","version":"latest","artifacts":[{"app":["Rolling.app"]}]},
          {"token":"case-sensitive","version":"2.0","artifacts":[{"app":["Case.app"]}]},
          {"token":"older","version":"1.0","artifacts":[{"app":["Older.app"]}]},
          {"token":"own-tool","version":"9.0","artifacts":[{"app":["Own.app"]}]}
        ]
        """#.utf8)
        let onlineCatalog = AppUpdatesSupport.parseOnlineCatalog(onlineCatalogBody) ?? []
        expect(onlineCatalog.count == 11
                && onlineCatalog.first?.bundleIDs == ["com.example.notes"]
                && onlineCatalog.first?.minimumOSVersions == ["14"]
                && onlineCatalog.first { $0.token == "writer" }?.appNames == ["Writer.app"],
               "the online catalog keeps final app names, explicit bundle identifiers and OS rules")
        expect(AppUpdatesSupport.parseOnlineCatalogResponse(onlineCatalogBody, statusCode: 200)?.count == 11
                && AppUpdatesSupport.parseOnlineCatalogResponse(nil, statusCode: 200) == nil
                && AppUpdatesSupport.parseOnlineCatalogResponse(onlineCatalogBody, statusCode: 500) == nil
                && AppUpdatesSupport.parseOnlineCatalogResponse(Data("broken".utf8), statusCode: 200) == nil,
               "missing, failed and malformed network responses never become successful empty coverage")

        let onlineApps = [
            AppUpdatesSupport.InstalledApp(name: "Notes", bundleID: "com.example.notes",
                                           path: "/Applications/Notes.app", version: "1.0",
                                           isFromAppStore: false),
